window.TSH_DATA={"perProject":[{"projectId":"ais","enrichment":[{"area":"전체 UI 구성·화면 구조","tech":"Next.js","role":"선박 추적 웹 앱의 골격을 잡고 화면을 페이지로 묶어 브라우저에 띄우는 토대 역할.","what":"여러 화면 조각(지도·사이드바)을 하나의 웹 페이지로 합쳐 주소를 입력하면 열리게 만들고, 화면을 미리 만들어 빠르게 보여 주는 웹 앱 프레임워크다.","withoutIt":"화면을 페이지로 묶고 주소(ops-main 등)에 연결하는 기본 구조를 직접 손으로 다 짜야 해서, 라우팅·빌드·초기 렌더링을 처음부터 다시 만들어야 한다.","example":"ops-main과 kyowa-line-ops 두 노선 버전을 각각 하나의 웹 페이지로 구성해 ais.vercel.co.kr/ops-main 주소로 열리게 한다."},{"area":"전체 UI 구성·화면 구조","tech":"React","role":"지도와 사이드바 같은 화면 영역을 재사용 가능한 부품(컴포넌트)으로 나눠 조립하는 역할.","what":"화면을 '지도 부품', '사이드바 부품'처럼 작은 조각으로 나누고, 데이터가 바뀌면 그 조각만 다시 그려 화면을 자동으로 갱신하는 도구다.","withoutIt":"화면 한 부분이 바뀔 때마다 어디를 어떻게 다시 그릴지 일일이 손으로 제어해야 해서, 선박이 움직일 때마다 화면 갱신이 꼬이기 쉽다.","example":"지도와 선박 상세 사이드바를 각각 React 컴포넌트로 만들어, 선박을 선택하면 사이드바 컴포넌트만 새 정보로 다시 그린다."},{"area":"지도·선박 마커 렌더링","tech":"Leaflet","role":"실제 바다 지도를 깔고 그 위 정확한 위경도 자리에 선박 점을 찍어 주는 지도 엔진 역할.","what":"세계 지도 타일을 화면에 띄우고, 위도·경도 좌표를 받아 그 위치에 선박 마커를 정확히 올려 놓고 확대·이동까지 처리해 주는 지도 라이브러리다.","withoutIt":"지도를 그리고 위경도를 화면 픽셀로 바꾸는 계산을 직접 해야 해서, 선박이 지도 위 엉뚱한 자리에 찍히거나 확대·드래그가 동작하지 않는다.","example":"관리 대상 선단(PEL·MAGE·OCEAN ACE)의 선박들을 Leaflet 지도 위 실제 위경도 자리에 마커로 찍어 실시간 위치를 보여 준다."},{"area":"선박 상세 정보 사이드바","tech":"React","role":"클릭한 선박의 항행 정보를 옆 패널에 정리해 띄우고, 선택이 바뀌면 그 내용을 즉시 갈아 끼우는 역할.","what":"사용자가 어떤 선박을 골랐는지 기억했다가, 그 선박의 MMSI·속도·침로·항행 상태를 사이드바 화면에 보기 좋게 채워 주는 화면 담당 부품이다.","withoutIt":"선박을 클릭해도 어떤 배가 선택됐는지 추적하고 패널 내용을 바꿔 끼우는 일을 직접 짜야 해서, 다른 선박을 눌러도 사이드바가 갱신되지 않는다.","example":"지도에서 한 선박 마커를 클릭하면 사이드바에 그 배의 MMSI·SOG·COG·항행 상태가 뜨고, 다른 배를 누르면 내용이 즉시 바뀐다."},{"area":"선박 상세 정보 사이드바","tech":"Leaflet","role":"지도 위 어떤 마커가 클릭됐는지 감지해 사이드바가 표시할 대상 선박을 알려 주는 역할.","what":"지도에 찍힌 선박 마커가 눌렸을 때 그 클릭을 잡아내서 '이 선박이 선택됐다'는 신호를 화면 쪽에 전달하는 지도 상호작용 처리다.","withoutIt":"지도 위 마커 클릭을 감지할 방법이 없어, 어떤 선박을 골랐는지 알 수 없고 사이드바에 무엇을 띄울지 정할 수 없다.","example":"Leaflet 마커의 클릭 이벤트로 선택된 선박을 식별해, 그 선박 정보를 React 사이드바에 넘겨 MMSI·속도 등을 표시한다."},{"area":"실시간 위치 자동 갱신","tech":"React","role":"일정 시간마다 선박 위치를 새로 받아 지도와 정보 패널을 자동으로 다시 그리게 하는 역할.","what":"사람이 새로고침을 누르지 않아도 주기적으로 최신 위치 데이터를 반영해 지도 위 선박과 사이드바 수치를 스스로 갱신하게 만드는 화면 갱신 처리다.","withoutIt":"위치가 바뀌어도 화면이 그대로 멈춰 있어, 선박을 '실시간 추적'하지 못하고 매번 수동으로 새로고침해야 한다.","example":"선박별 정보 패널과 함께 주기적으로 위치를 갱신해 지도상의 선박 마커가 실제 이동을 따라 움직이도록 한다."},{"area":"타입 안정성","tech":"TypeScript","role":"선박 데이터와 화면 부품이 다루는 값의 형태를 미리 정해 실수를 코딩 단계에서 잡아 주는 역할.","what":"MMSI·속도·침로 같은 선박 정보가 숫자인지 글자인지 형태를 미리 약속해 두고, 약속과 다른 값을 쓰면 작성 중에 바로 경고해 주는 도구다.","withoutIt":"속도에 잘못된 값이 들어가거나 없는 항목을 읽어도 실행하기 전엔 모르고, 배포 후 사이드바에 빈 값·오류가 뜨기 쉽다.","example":"선박 데이터 구조(MMSI·SOG·COG·항행 상태)와 UI 컴포넌트를 타입 기반으로 작성해, 잘못된 필드 접근을 코딩 단계에서 차단한다."},{"area":"두 노선 버전 배포·운영","tech":"Vercel","role":"완성된 웹 앱을 인터넷에 올려 실제 주소로 누구나 열 수 있게 호스팅하는 배포 플랫폼 역할.","what":"내 컴퓨터에서만 돌던 웹 앱을 인터넷 서버에 올려, ais.vercel.co.kr 같은 주소로 접속하면 바로 보이게 해 주는 배포·운영 서비스다.","withoutIt":"앱을 인터넷에 올리고 주소를 연결하고 서버를 관리하는 일을 직접 해야 해서, 다른 사람이 웹에서 선박 추적 화면을 열 수 없다.","example":"ops-main과 kyowa-line-ops 두 노선 버전을 Vercel에 올려 ais.vercel.co.kr/ops-main, /kyowa-line-ops 주소로 운영한다."},{"area":"두 노선 버전 배포·운영","tech":"Next.js","role":"같은 코드 기반에서 노선별 화면을 따로 구성해 두 버전으로 나눠 내보내는 역할.","what":"하나의 프로젝트 안에서 ops-main용 화면과 kyowa-line-ops용 화면을 각각의 경로로 만들어, 노선마다 다른 선단을 보여 주도록 묶어 내는 웹 앱 프레임워크다.","withoutIt":"노선마다 별도 프로젝트를 따로 만들고 중복 코드를 두 벌 관리해야 해서, 한쪽을 고치면 다른 쪽에 반영이 누락되기 쉽다.","example":"ops-main(PEL·MAGE·OCEAN ACE)과 kyowa-line-ops(KYOWA LINE)를 한 코드 기반의 두 노선 버전으로 빌드해 Vercel로 내보낸다."}],"scenarios":[{"layer":"시각화","currentTech":"Leaflet","currentMethod":"Leaflet 지도 타일 위에 선박 위경도를 마커(DOM/이미지 기반)로 찍고, 마커 클릭으로 선박을 선택한다.","altTech":"MapLibre GL JS (WebGL 벡터 지도)","affectedComponents":["지도·선박 마커 렌더링","선박 상세 정보 사이드바","실시간 위치 자동 갱신"],"methodChange":"래스터 타일 + DOM 마커 방식에서 WebGL 기반 벡터 지도 + GPU 심볼 레이어 방식으로 바뀐다. 선박을 개별 마커 대신 데이터 소스(GeoJSON) + symbol layer로 그리고, 클릭 감지는 Leaflet 마커 이벤트 대신 지도의 피처 쿼리(queryRenderedFeatures)로 처리한다.","visualChange":"지도를 부드럽게 회전·기울이고(3D 시점) 무단계로 확대해도 글자·선이 깨지지 않으며, 선박이 수백 척으로 늘어도 끊김 없이 부드럽게 움직인다. 반면 단순한 몇 척 추적에서는 체감 차이가 거의 없다.","metrics":{"perf":80,"complexity":65,"maintain":55,"bundle":35},"tradeoff":"장점: 선박 수가 많아질 때 훨씬 부드럽고, 벡터 지도라 확대해도 선명하다. 단점: WebGL 개념(레이어·소스·스타일 스펙)을 새로 배워야 하고 라이브러리 용량이 커서, 지금처럼 적은 선박만 다루면 학습 부담 대비 이득이 작다."},{"layer":"배포","currentTech":"Vercel","currentMethod":"Next.js 앱을 Vercel에 올려 ops-main / kyowa-line-ops 두 노선 버전을 자동 빌드·호스팅한다.","altTech":"GitHub Pages (정적 호스팅)","affectedComponents":["두 노선 버전 배포·운영","전체 UI 구성·화면 구조","실시간 위치 자동 갱신"],"methodChange":"Vercel의 서버 기능을 쓰던 Next.js 앱을 순수 정적 결과물(static export)로 빌드해 GitHub Pages에 올린다. 서버에서 처리하던 부분이 없어지고 모든 동작이 브라우저 안에서만 돌도록 바꿔야 하며, 위치 갱신용 데이터 요청도 외부에서 직접 받아오는 방식으로 옮겨야 한다.","visualChange":"사용자가 보는 지도·사이드바 화면 자체는 거의 동일하다. 다만 주소가 github.io 형태로 바뀌고, 서버가 없어 빌드 시점에 고정된 데이터만 보이므로 실시간 갱신 구성이 더 제한적으로 보일 수 있다.","metrics":{"perf":60,"complexity":45,"maintain":60,"bundle":50},"tradeoff":"장점: 완전 무료에 가깝고 설정이 단순하며 정적 파일이라 안정적이다. 단점: 서버 기능을 못 써서 실시간 데이터 연동·노선별 분기를 브라우저 쪽으로 옮겨야 하고, Vercel이 자동으로 해 주던 미리보기·빌드 편의가 사라진다."},{"layer":"UI상태","currentTech":"React (컴포넌트 내부 상태)","currentMethod":"선택된 선박·위치 데이터를 React 컴포넌트 상태로 들고, 선박을 클릭하면 그 상태를 바꿔 사이드바와 지도를 다시 그린다.","altTech":"Zustand (전역 상태 관리 라이브러리)","affectedComponents":["선박 상세 정보 사이드바","실시간 위치 자동 갱신","지도·선박 마커 렌더링"],"methodChange":"선택 선박·위치 같은 정보를 각 컴포넌트가 따로 들고 props로 넘기던 방식에서, 앱 전체가 공유하는 하나의 전역 저장소(store)에 모아 두고 필요한 컴포넌트가 직접 꺼내 쓰는 방식으로 바뀐다.","visualChange":"화면 동작과 보이는 모습은 동일하다. 내부적으로 지도·사이드바가 같은 선택 상태를 보고 있어, 선박 선택이 여러 패널에 더 일관되게 반영된다.","metrics":{"perf":65,"complexity":40,"maintain":75,"bundle":45},"tradeoff":"장점: 선택 선박·위치 데이터를 한 곳에서 관리해 컴포넌트가 늘어나도 데이터 전달이 깔끔해진다. 단점: 작은 앱에는 과한 도구일 수 있고, 라이브러리와 store 개념을 새로 익혀야 하는 약간의 학습 비용이 든다."}]},{"projectId":"sports","enrichment":[{"area":"2D 경기장 렌더링","tech":"HTML5 Canvas","role":"2D 매치 트래커 화면에서 경기장과 그 위를 움직이는 선수 22명·공을 실제로 그려내는 그리기 표면(캔버스) 역할","what":"한 장의 빈 도화지 같은 화면 위에, 좌표값(X·Y)으로 주어진 선수와 공을 점으로 콕콕 찍어 그린다. 시간이 흐르면 그 점들의 위치를 매 순간 다시 그려서 선수가 움직이는 것처럼 보이게 한다.","withoutIt":"위치 데이터(숫자 좌표)가 있어도 그것을 눈에 보이는 경기 장면으로 바꿔 보여줄 화면이 없어진다. 선수·공이 움직이는 2D 재현 자체가 불가능해지고, 표나 숫자 나열로만 남는다.","example":"DDUIM에서 Metrica Sports의 25Hz 실측 트래킹 좌표를 받아, 초록 경기장 위에 양 팀 선수 22명과 공을 점으로 찍어 경기 장면을 재현하는 바로 그 화면이 이 Canvas다. AIS Ship Tracker가 선박 좌표를 지도에 찍던 것과 같은 방식을 경기장에 적용했다."},{"area":"트래킹 데이터 파싱·재생 로직","tech":"JavaScript","role":"센서에서 나온 원본 위치 데이터를 프로그램이 이해할 수 있는 형태로 해석하고, 경기 장면을 시간 순서대로 되감기·재생하는 두뇌 역할","what":"웨어러블 센서(EPTS·GPS)가 기록한 '몇 초 몇 프레임에 누가 어디 있었는지'라는 시계열 데이터를 한 줄씩 읽어 정리하고, 시간 축을 따라 순서대로 화면에 흘려보내 영상처럼 재생되게 한다.","withoutIt":"원본 데이터는 그냥 숫자 묶음일 뿐이라, 이를 해석하고 시간 순으로 풀어내는 로직이 없으면 재생도 타임라인 이동도 멈춤도 전혀 안 된다. 경기가 '재생'된다는 핵심 기능이 사라진다.","example":"DDUIM에서 경기를 처음부터 틀거나, 타임라인을 잡고 특정 순간으로 점프하거나, 잠깐 멈췄다가 다시 트는 동작 모두 이 JavaScript 재생 엔진이 시계열 좌표를 시간 순으로 풀어주기 때문에 가능하다."},{"area":"선수별 분석·인터랙션 UI","tech":"JavaScript","role":"사용자의 클릭·타임라인 조작 같은 행동을 받아 화면 상태를 바꾸는 상호작용 처리 역할","what":"사용자가 특정 선수를 클릭하면 '지금 어느 점을 눌렀는지' 알아내 그 선수의 개별 분석을 띄우고, 타임라인을 움직이면 재생 위치를 그에 맞춰 바꾼다. 득점 순간에는 마커를 표시하도록 신호를 보낸다.","withoutIt":"화면이 그냥 자동 재생만 되는 동영상처럼 되어, 보고 싶은 선수를 골라 분석하거나 원하는 장면으로 건너뛰는 조작이 모두 불가능해진다.","example":"DDUIM에서 경기장 위 한 선수를 클릭해 그 선수 개별 분석을 보거나, 타임라인을 끌어 원하는 장면으로 이동하거나, 득점 마커를 누르는 인터랙션을 이 JavaScript 이벤트 처리가 담당한다."},{"area":"선수별 분석·인터랙션 UI","tech":"HTML5 Canvas","role":"클릭된 좌표를 실제 경기장 위 점·마커와 연결해 인터랙션의 '대상'이 되는 시각 요소를 제공하는 역할","what":"화면에 그려진 선수 점과 득점 마커가 곧 사용자가 누를 수 있는 대상이 된다. 어떤 점이 화면 어디에 그려졌는지를 알기에, 클릭한 위치와 가장 가까운 선수를 찾아낼 수 있게 해준다.","withoutIt":"클릭 처리 코드가 있어도 '화면의 이 자리에 어느 선수가 있는지'를 그려둔 시각 기준이 없으면, 무엇을 클릭했는지 짚어낼 대상 자체가 사라진다.","example":"DDUIM에서 경기장 위에 찍힌 선수 점과 득점 마커가 이 Canvas로 그려져 있기에, 사용자가 그 점을 정확히 클릭해 선수별 분석을 열 수 있다."},{"area":"화면 레이아웃·스타일링","tech":"Tailwind CSS","role":"경기장 캔버스·재생 컨트롤·분석 패널 등 화면 구성 요소들의 배치와 외형(색·여백·크기)을 잡아주는 디자인 도구 역할","what":"미리 준비된 짧은 스타일 이름표(유틸리티 클래스)를 요소에 붙이는 방식으로, 어디에 무엇을 놓고 색·간격·글자 크기를 어떻게 줄지 빠르게 지정한다. 직접 긴 디자인 코드를 쓰지 않아도 일관된 모양을 만든다.","withoutIt":"기능은 돌아가도 화면이 정렬되지 않고 버튼·패널이 제멋대로 배치돼, 매치 트래커가 다듬어진 웹 앱이 아니라 거친 시제품처럼 보인다. 디자인을 일일이 손으로 작성해야 해 작업이 크게 느려진다.","example":"DDUIM 2D 매치 트래커에서 경기장, 타임라인 바, 선수 분석 패널이 보기 좋게 배치되고 색·여백이 통일돼 보이는 것은 이 Tailwind CSS 유틸리티 클래스로 레이아웃과 스타일을 구성했기 때문이다."},{"area":"실측 트래킹 데이터 연동","tech":"EPTS 트래킹 데이터","role":"시뮬레이터가 보여주는 모든 움직임의 원천이 되는, 실제 경기에서 측정된 선수·공 위치 데이터(연료) 역할","what":"광학 트래킹으로 실제 경기에서 측정한 선수·공의 시간대별 위치를 EPTS라는 표준 형식으로 담은 데이터다. 가짜로 지어낸 움직임이 아니라 실측값이라, 재현 장면이 실제 경기 흐름과 일치한다.","withoutIt":"이 실측 데이터가 없으면 시뮬레이터는 보여줄 내용이 없거나, 임의로 꾸며낸 가짜 움직임만 재생하게 된다. '실제 경기를 2D로 재현한다'는 프로젝트의 핵심 전제가 무너진다.","example":"DDUIM은 Metrica Sports가 공개한 25Hz 광학 트래킹 실측 경기 데이터를 EPTS 형식으로 연동해 구동한다. 다만 임의의 최신 경기 연속 트래킹은 비공개 상업 데이터라 무료로 못 구하는 점이 디렉터가 개발을 잠정 보류한 핵심 사유다."}],"scenarios":[{"layer":"시각화","currentTech":"HTML5 Canvas","currentMethod":"빈 캔버스 한 장에 매 프레임마다 선수 22명과 공의 좌표를 점으로 직접 찍어 다시 그린다(즉시 모드 그리기). 화면 전체를 매번 새로 그려 재생 애니메이션을 만든다.","altTech":"SVG (DOM 기반 벡터 그래픽)","affectedComponents":["2D 경기장 렌더링","선수별 분석·인터랙션 UI","트래킹 데이터 파싱·재생 로직"],"methodChange":"점을 매 프레임 직접 그리는 대신, 선수마다 하나의 SVG 원(circle) 요소를 만들어 두고 좌표가 바뀔 때 그 요소의 위치 속성만 갱신한다. 선수 클릭 처리도 캔버스 좌표 역계산 대신 각 원 요소에 클릭 이벤트를 직접 붙여 처리하게 바뀐다.","visualChange":"화면 결과물(경기장 위 움직이는 점)은 거의 동일하나, 선수마다 개별 요소가 생겨 클릭 대상을 짚기 쉬워지고 외곽선·툴팁 같은 꾸밈을 붙이기 편해진다. 다만 선수·공·잔상까지 요소 수가 많아지면 25Hz 같은 빠른 재생에서 화면이 버벅일 수 있다.","metrics":{"perf":45,"complexity":40,"maintain":65,"bundle":50},"tradeoff":"장점: 선수마다 요소가 따로 있어 클릭·강조·툴팁 처리가 직관적이고, 화면 확대해도 점이 깨지지 않는다. 단점: 22명+공+잔상이 모두 개별 요소가 되면 25Hz 빠른 재생에서 캔버스보다 느려지기 쉽다. 초보자에겐 다루기 쉬운 편이지만 많은 점을 동시에 빠르게 움직이는 이 프로젝트엔 성능이 약점."},{"layer":"데이터","currentTech":"EPTS 트래킹 데이터 (연속 광학 트래킹)","currentMethod":"선수·공의 매 순간 X·Y 좌표가 끊김 없이 이어진 25Hz 시계열 데이터를 파싱해, 모든 프레임의 위치를 그대로 화면에 재생한다.","altTech":"이벤트 데이터 (패스·슈팅·태클 등 사건 단위 기록)","affectedComponents":["트래킹 데이터 파싱·재생 로직","2D 경기장 렌더링","실측 트래킹 데이터 연동"],"methodChange":"매 프레임 좌표를 그대로 재생하는 대신, '몇 분에 누가 어디서 패스/슈팅을 했다'는 사건 좌표만 받아 그 사이 구간은 프로그램이 직선·곡선으로 채워(보간) 움직임을 추정해 그린다. 연속 좌표 파서 대신 사건 목록 파서와 보간 로직이 들어간다.","visualChange":"실제 발걸음 하나하나가 아니라 사건과 사건 사이를 매끄럽게 이어 붙인 근사 움직임이 되어, 미세한 몸놀림은 사라지고 큰 흐름(패스 경로·슈팅 위치)만 보인다. 대신 비공개 유료 트래킹 없이도 더 많은 경기를 다룰 가능성이 열린다.","metrics":{"perf":70,"complexity":55,"maintain":60,"bundle":45},"tradeoff":"장점: 이벤트 데이터는 연속 광학 트래킹보다 구하기 쉬워(디렉터가 보류 사유로 든 데이터 수급 장벽을 일부 우회) 더 많은 경기를 재현할 수 있고, 데이터 양이 적어 가볍고 빠르다. 단점: 사건 사이를 추정으로 채우므로 실제 선수 움직임의 정밀함이 떨어진다 — '실측 재현'의 충실도가 낮아지는 절충."},{"layer":"스타일","currentTech":"Tailwind CSS","currentMethod":"요소마다 미리 정의된 유틸리티 클래스 이름표(예: 여백·색·정렬 클래스)를 붙여 레이아웃과 외형을 구성한다.","altTech":"순수 CSS (직접 작성하는 스타일시트)","affectedComponents":["화면 레이아웃·스타일링","선수별 분석·인터랙션 UI"],"methodChange":"클래스 이름표를 붙이는 대신, 별도 스타일 파일에 경기장·타임라인·분석 패널 각각의 디자인 규칙을 직접 손으로 작성한다. 색·여백 값을 한 곳에 모아 변수로 관리하게 된다.","visualChange":"최종 화면 모양은 동일하게 만들 수 있으나, 디자인을 바꿀 때 클래스만 갈아끼우는 대신 스타일 파일을 직접 수정해야 한다. 작은 화면 대응이나 일관성 유지에 손이 더 간다.","metrics":{"perf":75,"complexity":50,"maintain":45,"bundle":80},"tradeoff":"장점: 외부 도구 의존이 없어 최종 결과물이 가볍고, 스타일을 완전히 내 마음대로 통제할 수 있다. 단점: 모든 디자인을 직접 써야 해 작업이 느리고, 화면 곳곳의 통일감을 유지하기 어려워 초보자가 실수하기 쉽다 — Tailwind가 주던 빠른 일관 스타일링의 이점을 잃는다."}]},{"projectId":"solar","enrichment":[{"area":"3D 우주 렌더링·카메라 조작","tech":"Three.js","role":"WebGL을 직접 다루지 않고도 씬·카메라·조명·메시를 객체로 다루게 해주는 3D 엔진 계층. 이 화면의 우주 전체를 구성하고 그려내는 뼈대 역할.","what":"태양·행성·달·배경별을 3차원 공간 안에 배치하고, 카메라가 보는 방향대로 매 순간 화면에 그려준다. PerspectiveCamera로 원근감을 주고 OrbitControls로 마우스 드래그 회전·휠 줌·관성(damping)을 처리한다.","withoutIt":"WebGL 명령(버퍼·셰이더·행렬)을 손으로 일일이 작성해야 해서 행성 하나 띄우는 데도 수백 줄이 필요하고, 카메라 회전·줌 같은 기본 조작도 직접 수학으로 구현해야 한다.","example":"PointLight로 태양빛을 쏘고 PCFSoftShadowMap으로 그림자를 만들며, 사용자가 마우스를 드래그하면 OrbitControls가 태양계를 부드럽게 돌려 보여준다."},{"area":"3D 우주 렌더링·카메라 조작","tech":"WebGL","role":"브라우저가 그래픽카드(GPU)에 직접 그림을 그리게 하는 저수준 렌더링 기술. Three.js가 내부적으로 의존하는 실제 그리기 엔진.","what":"수많은 별과 행성, 셰이더 효과를 CPU가 아닌 GPU에서 한꺼번에 계산해 부드럽게 60프레임으로 움직이게 한다.","withoutIt":"GPU 가속이 없으면 천체가 많아질수록 화면이 끊기고, 셰이더로 표현하는 태양 표면·블랙홀 같은 실시간 그래픽 효과 자체가 불가능하다.","example":"WebGLRenderer를 antialias·logarithmicDepthBuffer 옵션으로 생성해, 가까운 달부터 수만 AU 밖 오르트 구름까지 깊이 충돌(z-fighting) 없이 한 화면에 렌더한다."},{"area":"3D 우주 렌더링·카메라 조작","tech":"JavaScript","role":"렌더 루프·이벤트·상태를 한데 묶어 시뮬레이터를 실제로 구동시키는 프로그래밍 언어. 모든 로직의 접착제 역할.","what":"매 프레임마다 카메라·조명·천체 위치를 갱신하고 사용자 입력에 반응하도록 전체 흐름을 제어한다.","withoutIt":"Three.js로 만든 객체들을 움직이거나 사용자 조작에 연결할 수단이 없어, 정지된 한 장면만 남는다.","example":"requestAnimationFrame 루프 안에서 카메라 트윈 추적과 OrbitControls 업데이트, 천체 위치 재계산을 매 프레임 호출한다."},{"area":"날짜 기반 천체력 엔진(8행성·달)","tech":"JavaScript","role":"실제 천문학 공식(케플러 궤도요소)을 코드로 옮겨, 입력한 날짜에 맞는 천체의 진짜 위치를 계산하는 두뇌 역할.","what":"임의의 날짜를 넣으면 그날 태양·8행성·달이 우주 어디에 있었는지를 수학으로 역산한다. 달은 흔들림을 보정하는 섭동항 12개까지 더해 더 정밀하게 계산한다.","withoutIt":"천체가 대충 원을 그리며 도는 가짜 애니메이션이 되어, 「실제 시각 기준 케플러 궤도력대로 움직인다」는 이 프로젝트의 핵심 가치가 사라진다.","example":"공전주기를 실제 관측값 대비 오차 최대 0.22퍼센트로 재현해, 과거·미래 어느 날짜로 타임머신을 돌려도 그 시점의 행성 배치를 보여준다."},{"area":"행성·위성 표면 텍스처","tech":"Three.js (TextureLoader)","role":"외부 이미지 파일을 3D 구(sphere) 표면에 입히는 텍스처 적용 계층. 행성을 사실적으로 보이게 하는 옷 입히기 역할.","what":"NASA가 만든 행성 표면 사진(디퓨즈)과 요철 정보(범프)를 행성·고리 모델에 입혀, 밋밋한 공이 아니라 진짜 행성처럼 보이게 한다.","withoutIt":"행성이 전부 단색 공처럼 보여 수성·화성·목성을 색만으로 구분하기 어렵고, 토성 고리의 실제 색 띠도 표현되지 않는다.","example":"jsDelivr의 threex.planets에서 7행성의 NASA 텍스처를 TextureLoader로 불러와 적용하고, 토성 고리에도 실제 색 텍스처를 입힌다."},{"area":"행성·위성 표면 텍스처","tech":"Canvas 2D (절차적 생성)","role":"이미지 텍스처가 없는 천체를 위해 코드로 무늬를 그려내는 보조 텍스처 생성기 역할.","what":"텍스처 파일이 없는 가스행성·암석행성에 대해, 띠무늬나 크레이터 패턴을 프로그램이 즉석에서 그려 표면 이미지로 만든다.","withoutIt":"공개 텍스처가 없는 천체는 완전 단색이 되어, 가스행성의 줄무늬나 암석 표면의 질감을 전혀 줄 수 없다.","example":"텍스처가 없는 행성에 Canvas 2D로 띠·크레이터 패턴을 절차적으로 그려 표면 맵으로 사용한다."},{"area":"지구·태양·위성 GLSL 셰이더","tech":"GLSL","role":"GPU 위에서 픽셀 하나하나의 색을 직접 계산하는 셰이더 언어. 사진 텍스처로는 불가능한 살아 움직이는 표면 효과를 만드는 역할.","what":"태양 표면이 끓는 모양, 흑점, 가장자리 어두워짐(limb darkening) 같은 효과를 매 프레임 실시간으로 계산해 그린다. 위성마다 다른 표면 질감도 코드로 생성한다.","withoutIt":"태양이 그냥 노란 공으로 멈춰 있고, 가스행성의 대기 후광이나 위성별 고유 표면 같은 동적 효과를 전혀 표현할 수 없다.","example":"태양은 ShaderMaterial로 fbm 노이즈 granulation·흑점·limb darkening을 실시간 렌더하고, 11개 위성은 CRATERED·VOLCANIC·ICY·HAZY 4종 절차적 셰이더로 각자 다른 표면을 그린다."},{"area":"지구·태양·위성 GLSL 셰이더","tech":"Three.js (ShaderMaterial)","role":"직접 작성한 GLSL 코드를 Three.js 객체에 연결해주는 다리 역할. 셰이더를 행성 메시에 입히는 통로.","what":"개발자가 쓴 GLSL 셰이더와 uniform 값(시간·투명도 등)을 받아 해당 천체에 적용하고, normalMap·구름·야경 같은 여러 레이어를 합친다.","withoutIt":"GLSL 코드를 작성해도 그것을 실제 행성 모델에 입힐 표준 연결고리가 없어, 셰이더 효과를 화면에 띄울 수 없다.","example":"지구는 normalMap·구름·야경 emissiveMap 레이어를 ShaderMaterial로 합치고, 가스행성은 Fresnel 기반 atmospheric halo를 입힌다."},{"area":"인터스텔라·블랙홀 셰이더 시스템","tech":"GLSL","role":"영화 「인터스텔라」급 블랙홀·웜홀의 복잡한 빛 현상을 GPU에서 직접 계산하는 특수 셰이더 역할.","what":"블랙홀 강착원반의 회전, 플라즈마 노이즈, 한쪽이 더 밝아지는 도플러 빔잉, 중력으로 빛이 휘는 렌즈 효과를 실시간으로 그린다.","withoutIt":"블랙홀과 웜홀이 평범한 원반·구로 보여, 가르강튀아의 휘어진 빛고리나 별빛 중력렌즈 같은 과학적 시각 효과를 재현할 수 없다.","example":"가르강튀아 강착원반에 케플러 회전·fBm 플라즈마·도플러 빔잉·view-dependent UV warp을 GLSL로 표현하고, EHT(M87) 블랙홀과 웜홀은 각각 별도 셰이더로 photon ring·중력렌즈·별 분광형 분포를 렌더한다."},{"area":"인터스텔라·블랙홀 셰이더 시스템","tech":"WebGL","role":"여러 개의 무거운 블랙홀·웜홀 셰이더를 동시에 GPU에서 돌려도 화면이 끊기지 않게 하는 실행 기반 역할.","what":"복잡한 셰이더 연산을 GPU 병렬 처리로 감당해, 인터스텔라 시스템을 다른 천체들과 한 씬에서 부드럽게 함께 보여준다.","withoutIt":"GPU 가속 없이는 이렇게 연산량이 큰 다중 셰이더 효과가 프레임을 떨어뜨려 사실상 재생 불가능하다.","example":"가르강튀아·EHT 블랙홀·웜홀의 서로 다른 ShaderMaterial 3종을 WebGL이 동시에 렌더하며, 카메라 far를 1.2e6까지 확장해도 유지된다."},{"area":"조석·실시간 달 위젯 UI","tech":"JavaScript","role":"천체 인력을 물리 공식으로 계산해 조석(물때)을 산출하고 달 위상을 구하는 계산 로직 역할.","what":"부산 기준으로 달·태양의 인력에 따른 이론 평형조석을 계산해 물때와 조석곡선을 만들고, 현재 시각의 달 위상과 조명률을 구한다.","withoutIt":"조석곡선·물때 패널과 달 위상이 실제 천체 위치와 무관한 장식이 되어, 「실시간」이라는 위젯의 의미가 사라진다.","example":"부산 기준 평형조석을 천체 인력으로 계산해 48시간 조석곡선을 그리고, 한국어 8단계 위상명과 조명률을 산출해 달 위젯에 표시한다."},{"area":"조석·실시간 달 위젯 UI","tech":"HTML5 (Canvas 2D)","role":"계산된 조석곡선과 달 모양을 2D 그림으로 실제 그려내는 표시 레이어 역할.","what":"조석곡선을 Canvas에 곡선으로 그리고, NASA 달 텍스처를 합성 방식으로 그려 위상에 따른 그림자만 정확히 바뀌게 한다.","withoutIt":"계산 결과를 숫자로만 둘 수밖에 없어, 직관적인 물때 그래프와 사실적인 달 그림을 사용자에게 보여줄 수 없다.","example":"달 위젯은 NASA moon 텍스처를 Canvas 2D globalCompositeOperation multiply로 합성해 표면 디테일은 유지하면서 위상별 그림자만 변화시킨다."},{"area":"인터랙션·라벨·탐사선 마커","tech":"Three.js (Raycaster·Sprite)","role":"마우스 클릭을 3D 공간의 천체와 연결하고, 이름표·탐사선 마커를 3D 안에 띄우는 상호작용 계층 역할.","what":"화면 클릭 위치에서 가상의 광선(raycaster)을 쏴 어떤 천체를 눌렀는지 알아내고, 이름표는 항상 카메라를 향하는 Sprite 빌보드로, 탐사선은 메시와 점선 항적으로 표시한다.","withoutIt":"천체를 클릭해도 무엇을 골랐는지 알 수 없고, 이름표가 3D 회전 시 뒤집히거나 탐사선이 점 하나로만 보인다.","example":"천체를 클릭하면 raycaster로 선택해 사이드바에 정보를 띄우고 카메라가 트윈으로 추적하며, 보이저·뉴호라이즌스·파커·JWST를 Mesh 그룹과 LineDashedMaterial 항적으로 표시한다."},{"area":"인터랙션·라벨·탐사선 마커","tech":"JavaScript","role":"클릭 이벤트와 카메라 추적, 사이드바 정보 갱신을 묶는 인터랙션 제어 로직 역할.","what":"어떤 천체가 선택됐는지 상태를 관리하고, 그에 맞춰 카메라를 부드럽게 옮기며 사이드바 내용을 바꾼다.","withoutIt":"선택·추적·정보 표시가 서로 연결되지 않아, 클릭해도 카메라가 따라가거나 정보가 갱신되지 않는다.","example":"선택된 천체로 카메라를 트윈 추적시키고, raycaster 결과에 따라 사이드바에 지름·공전주기 등 정보를 채운다."},{"area":"배포·로딩","tech":"GitHub Pages","role":"별도 서버 없이 정적 웹 파일을 인터넷에 공개하는 무료 호스팅 역할.","what":"단일 index.html 파일을 웹 주소로 올려, 누구나 브라우저에서 시뮬레이터에 접속할 수 있게 한다.","withoutIt":"직접 서버를 마련·운영해야 해서, 개인이 만든 시뮬레이터를 손쉽게 공개하기 어렵다.","example":"단일 index.html을 GitHub Pages로 배포해 gmpark-creator.github.io 주소로 태양계 시뮬레이터를 공개한다."},{"area":"배포·로딩","tech":"HTML5 (importmap·로딩 화면)","role":"외부 라이브러리를 ES 모듈로 불러오고 초기 로딩 동안 사용자를 안심시키는 진입점 역할.","what":"importmap으로 CDN의 Three.js 모듈 경로를 지정해 빌드 도구 없이 바로 로드하고, 텍스처를 받는 동안 로딩 스피너를 보여준다.","withoutIt":"모듈 경로를 매번 전체 URL로 써야 하고, 텍스처 로딩 중 빈 화면이 나와 사용자가 멈춘 줄 오해한다.","example":"importmap으로 jsDelivr CDN의 three.module.js와 OrbitControls를 ES module로 로드하고, CDN 텍스처를 받는 동안 로딩 스피너 화면을 표시한다."}],"scenarios":[{"layer":"시각화","currentTech":"Three.js + 커스텀 GLSL ShaderMaterial","currentMethod":"WebGLRenderer로 GPU 렌더링하고, 태양·블랙홀·위성 표면을 직접 작성한 GLSL 셰이더로 매 프레임 실시간 계산해 그린다.","altTech":"CSS 3D Transform + DOM 요소","affectedComponents":["3D 우주 렌더링·카메라 조작","지구·태양·위성 GLSL 셰이더","인터스텔라·블랙홀 셰이더 시스템","행성·위성 표면 텍스처"],"methodChange":"GPU 셰이더 대신 HTML 요소(div)에 CSS transform: rotate3d·translate3d를 걸어 천체를 의사 3D로 배치한다. 태양 granulation·블랙홀 도플러·위성별 절차적 표면 같은 픽셀 단위 효과는 미리 만든 PNG 이미지나 CSS 그라데이션·애니메이션으로 대체한다.","visualChange":"행성은 평면 원판이 카메라를 향하는 빌보드처럼 보이고 진짜 구체감·실시간 표면 끓음·중력렌즈가 사라진다. 별·행성이 많아지면 회전 시 눈에 띄게 끊긴다.","metrics":{"perf":35,"complexity":30,"maintain":55,"bundle":80},"tradeoff":"장점: WebGL/GLSL 지식 없이 익숙한 HTML·CSS만으로 만들 수 있고 라이브러리 의존이 줄어 번들이 가볍다. 단점: 실시간 셰이더 효과(끓는 태양·휘는 블랙홀)가 불가능하고, 천체 수가 늘면 성능이 급격히 나빠져 이 프로젝트가 자랑하는 비주얼을 거의 포기하게 된다."},{"layer":"배포","currentTech":"GitHub Pages + importmap(jsDelivr CDN) 정적 호스팅","currentMethod":"빌드 도구 없이 단일 index.html을 GitHub Pages에 올리고, importmap으로 CDN의 three.module.js·OrbitControls를 브라우저에서 직접 ES module로 로드한다.","altTech":"Vite 번들러 + Netlify/Vercel 배포","affectedComponents":["배포·로딩","3D 우주 렌더링·카메라 조작"],"methodChange":"Three.js를 CDN importmap이 아니라 npm으로 설치해 import하고, Vite로 번들·트리셰이킹·코드 분할한 결과물을 Netlify/Vercel이 빌드해 배포한다. 텍스처 등 에셋도 빌드 파이프라인이 최적화·해싱한다.","visualChange":"사용자가 보는 화면 자체는 동일하지만, 초기 로딩이 빨라지고(번들 최적화·캐시) CDN 장애에 영향받지 않아 첫 로딩 스피너가 보이는 시간이 줄어든다.","metrics":{"perf":70,"complexity":60,"maintain":65,"bundle":55},"tradeoff":"장점: 로딩 속도·캐싱·CDN 독립성이 좋아지고 의존성 버전을 package.json으로 고정 관리할 수 있다. 단점: node·npm·번들러 설정을 배우고 빌드 단계를 거쳐야 해서, 파일 하나 올리면 끝이던 현재 방식보다 입문자에게 진입 장벽과 유지 부담이 커진다."},{"layer":"데이터","currentTech":"JavaScript 케플러 궤도력 엔진(자체 수학 역산)","currentMethod":"케플러 궤도요소(2000.0 기준값 + 1일당 변화율)와 달 섭동항 12개를 직접 코드로 계산해 임의 날짜의 천체 위치를 역산한다.","altTech":"사전 계산된 천체력 데이터(NASA JPL Horizons) + JSON 보간","affectedComponents":["날짜 기반 천체력 엔진(8행성·달)","조석·실시간 달 위젯 UI"],"methodChange":"런타임에 궤도 공식을 푸는 대신, JPL Horizons에서 미리 뽑아둔 날짜별 위치 표를 JSON으로 싣고 두 시점 사이를 보간(interpolation)해 위치를 구한다.","visualChange":"데이터 표가 포함된 날짜 구간 안에서는 위치 정확도가 더 높아질 수 있으나, 표 범위를 벗어난 먼 과거·미래 날짜로 타임머신을 돌리면 위치를 구하지 못해 재생이 막힌다.","metrics":{"perf":75,"complexity":45,"maintain":40,"bundle":35},"tradeoff":"장점: 매 프레임 공식 계산이 줄어 연산이 가볍고, 권위 있는 NASA 실측 데이터로 특정 구간 정확도를 높일 수 있다. 단점: 데이터 파일이 번들에 들어가 무거워지고, 데이터에 없는 임의 날짜로의 무제한 타임머신이라는 현재 강점을 잃으며, 표 갱신·관리 부담이 생긴다."}]},{"projectId":"inst","enrichment":[{"area":"백엔드 API 서버·라우팅","tech":"FastAPI","role":"브라우저가 보낸 음원 파일을 받아 추출 엔진으로 넘기고 결과를 돌려주는 백엔드의 현관·교통정리 역할.","what":"main.py에서 웹 서버 앱을 만들어 주소(/, /health, /extract)별로 요청을 어떤 처리로 보낼지 길을 나눠준다. 사용자가 올린 파일과 모델 선택값을 받아 처리 함수로 전달한다.","withoutIt":"이게 없으면 브라우저 UI에서 올린 음원을 받아줄 서버 입구가 없어, 웹 화면과 GPU 추출 코드가 서로 연결되지 못하고 실제 분리 요청을 보낼 수 없다.","example":"이 프로젝트에서 드롭존에 음원을 끌어다 놓으면 FormData가 /extract 엔드포인트로 POST되고, /health로는 서버가 살아있는지 점검한다."},{"area":"백엔드 API 서버·라우팅","tech":"Python 3.12","role":"백엔드 전체 로직(서버·추출·검증)을 실제로 굴리는 기반 언어.","what":"FastAPI 앱, demucs 호출, 파일 검증 같은 서버 쪽 코드를 모두 파이썬으로 작성해 한 프로세스로 실행한다.","withoutIt":"기반 언어가 없으면 FastAPI도 Demucs도 동작할 토대가 사라져 백엔드 자체가 성립하지 않는다. demucs·torch 같은 AI 라이브러리가 파이썬 생태계라 다른 언어로는 그대로 못 쓴다.","example":"이 프로젝트에서 main.py 한 파일에 서버 라우팅과 separate_instrumental() 추출 로직이 모두 파이썬으로 들어가 있다."},{"area":"보컬 제거·반주 분리 엔진","tech":"Demucs","role":"음원을 보컬·드럼·베이스·기타 등 스템으로 쪼개는 이 프로젝트의 본질 기능(보컬 제거)을 수행하는 AI 분리 모델.","what":"get_model로 학습된 분리 모델을 불러오고 apply_model로 한 곡을 여러 악기 스템으로 분해한 뒤, 보컬 스템만 빼고 나머지를 다시 합쳐 반주를 만든다.","withoutIt":"이게 없으면 음원에서 목소리만 골라 지우는 핵심 변환 능력이 사라져, 프로젝트가 하려는 '반주 추출' 자체가 불가능해진다.","example":"이 프로젝트에서 apply_model(split=True, overlap=0.25, shifts=1)로 스템을 나눈 뒤 vocals를 제외한 나머지를 합산해 Inst 트랙을 만든다."},{"area":"보컬 제거·반주 분리 엔진","tech":"PyTorch CUDA","role":"Demucs 모델의 무거운 연산을 그래픽카드(GPU)로 빠르게 돌려주는 연산 엔진.","what":"AI 모델이 음원을 분석할 때 필요한 대량의 행렬 계산을 NVIDIA GPU에서 병렬로 처리해, 분리 작업을 CPU보다 훨씬 빠르게 끝낸다.","withoutIt":"이게 없으면 분리 연산을 느린 CPU로만 돌려야 해서 한 곡 처리에 시간이 크게 늘고, GPU 가속이 전제인 실시간성 좋은 추출 경험이 무너진다.","example":"이 프로젝트에서 RTX 4060 Ti로 demucs 직호출이 1.86초에 끝났고 VRAM 543MB를 썼다고 검증됐다."},{"area":"GPU 자동 디바이스 분기·모델 캐시","tech":"PyTorch CUDA","role":"실행 환경에 GPU가 있으면 자동으로 GPU를, 없으면 CPU를 쓰게 골라주고 한 번 불러온 모델을 재사용하게 해주는 효율·호환 담당.","what":"torch.cuda.is_available()로 그래픽카드 사용 가능 여부를 확인해 처리 장치를 자동으로 정하고, 이미 메모리에 올려둔 모델은 다시 안 불러오고 캐시에서 꺼내 쓴다.","withoutIt":"이게 없으면 GPU 없는 PC에서 코드가 멈추거나, 매 요청마다 모델을 새로 로드해 처리 시작이 느려지고 메모리를 낭비한다.","example":"이 프로젝트에서 (model_name, device)를 키로 _MODEL_CACHE에 모델을 저장해 같은 모델 재호출 시 로드 비용을 줄인다."},{"area":"결과 오디오 WAV 출력","tech":"PyTorch CUDA","role":"분리가 끝난 반주 데이터(텐서)를 실제 오디오로 저장하기 직전 안전하게 다듬는 후처리 담당.","what":"GPU에서 계산된 반주 음파 데이터의 값 범위를 -1~1로 잘라(clamp) 소리가 깨지지 않게 정리한 뒤, 저장 가능한 일반 숫자 배열(numpy)로 변환한다.","withoutIt":"이게 없으면 범위를 벗어난 음파 값이 그대로 들어가 출력 파일에 클리핑·잡음이 생기거나, GPU 텐서를 파일로 못 바꿔 저장 단계에서 실패한다.","example":"이 프로젝트에서 합산한 반주 텐서를 clamp(-1,1) 후 numpy로 바꿔 다음 저장 단계로 넘긴다."},{"area":"결과 오디오 WAV 출력","tech":"Demucs","role":"분리 모델이 내놓은 여러 스템을 모아 최종 반주 한 트랙으로 합쳐 결과물 형태를 결정하는 담당.","what":"모델이 쪼갠 스템들 중 보컬을 뺀 나머지(드럼·베이스·기타 등)를 더해 하나의 반주 음원으로 만들고, 이를 WAV 파일로 떨어뜨릴 수 있는 형태로 정리한다.","withoutIt":"이게 없으면 분리는 됐어도 스템들이 흩어진 채라 '보컬 없는 반주 한 곡'이라는 사용자가 원하는 최종 결과물이 만들어지지 않는다.","example":"이 프로젝트에서 분리·합산한 반주를 soundfile로 PCM_16 WAV 파일로 OUTPUT_DIR에 저장한다."},{"area":"믹싱 콘솔 프론트엔드 UI","tech":"HTML5","role":"사용자가 음원을 올리고 진행 상황을 보고 결과를 받는 화면 구조 자체를 만드는 골격.","what":"index.html에 드래그앤드롭 드롭존, 모델 선택, 진행바, VU 미터, 완료 팝업 같은 화면 요소를 배치해 믹싱 콘솔 콘셉트의 작업 화면을 구성한다.","withoutIt":"이게 없으면 사용자가 파일을 끌어다 놓거나 진행 상태를 볼 화면 자체가 없어, 백엔드가 아무리 강력해도 사람이 쓸 입구가 사라진다.","example":"이 프로젝트에서 다크 믹싱 콘솔 카드 안에 드롭존·진행바(shimmer)·VU 미터·Lucide 아이콘을 HTML 구조로 배치했다."},{"area":"믹싱 콘솔 프론트엔드 UI","tech":"Tailwind","role":"화면을 별도 CSS 파일 없이 클래스만으로 빠르게 다크 믹싱 콘솔 톤으로 꾸미는 스타일 담당.","what":"HTML 요소에 미리 정의된 유틸리티 클래스를 붙여 색·간격·그림자·다크 테마 같은 시각 스타일을 바로 입힌다. CDN으로 불러와 설치 과정 없이 쓴다.","withoutIt":"이게 없으면 모든 카드·버튼·진행바 스타일을 직접 CSS로 일일이 작성해야 해 화면 꾸미기가 느려지고, 믹싱 콘솔 같은 통일된 다크 톤을 잡기 번거로워진다.","example":"이 프로젝트에서 Tailwind CDN으로 다크 믹싱 콘솔 카드의 색·레이아웃을 클래스만으로 구성했다."},{"area":"데모 모드·실제 추출 분기 로직","tech":"HTML5","role":"백엔드가 없는 외부 방문자도 UI를 체험하게 하거나, 본인 PC에서는 실제 추출을 호출하게 두 동작을 나누는 프론트 분기 담당.","what":"데모 모드 토글이 켜져 있으면 서버 없이 브라우저 안에서 가짜 처리 흐름을 보여주고, 꺼지면 실제 백엔드로 파일을 보내 진짜 분리를 요청하도록 화면 동작을 가른다.","withoutIt":"이게 없으면 GPU 백엔드가 없는 외부인은 페이지를 열어도 곧장 에러만 보게 되고, 공개 웹 보고서에서 UI를 안전하게 체험시키는 방법이 없어진다.","example":"이 프로젝트에서 사무실 데모 모드 ON이면 5초 가상 처리 후 무음 WAV를 만들고, OFF면 FormData로 /extract에 POST해 실제 분리를 호출한다."},{"area":"업로드 검증·모델 화이트리스트","tech":"FastAPI","role":"들어오는 업로드 요청의 파일과 모델명이 허용 범위인지 입구에서 걸러내는 안전장치 담당.","what":"FastAPI가 받은 업로드 파일의 확장자가 허용 목록에 있는지, 요청한 모델명이 지원 목록에 있는지 확인하고, 파일이 너무 크면 저장 도중 끊고 에러를 돌려준다.","withoutIt":"이게 없으면 지원 안 되는 형식·존재하지 않는 모델·과도하게 큰 파일이 그대로 들어와 추출 엔진이 엉뚱하게 멈추거나 서버 자원이 고갈될 수 있다.","example":"이 프로젝트에서 ALLOWED_SUFFIXES 확장자 검증과 SUPPORTED_MODELS 화이트리스트로 거르고, MAX_UPLOAD_BYTES 초과 시 413 에러를 반환한다."},{"area":"비ASCII 파일명 헤더 처리","tech":"FastAPI","role":"일본어·한글 같은 비영문 파일명을 응답에 안전하게 실어 보내 인코딩 오류를 막는 호환 담당.","what":"원본 파일명을 그대로 HTTP 헤더에 넣으면 영문 외 글자에서 인코딩 제한에 걸리므로, 파일명을 퍼센트 인코딩(예: %ED%95%9C)으로 바꿔 전용 헤더에 담아 돌려준다.","withoutIt":"이게 없으면 일본어·한글 파일명을 올렸을 때 분리는 성공해도 응답 단계에서 500 에러가 나, 사용자가 결과 파일을 못 받는다.","example":"이 프로젝트에서 일본어 MP3 업로드 시 500이 나던 문제를, 원본 파일명을 X-Original-Filename-Encoded 헤더에 urllib.parse.quote로 인코딩해 해결했다."}],"scenarios":[{"layer":"데이터","currentTech":"Demucs (htdemucs 계열)","currentMethod":"get_model로 demucs 모델을 로드하고 apply_model(split=True, overlap=0.25, shifts=1)로 음원을 스템 단위로 분리한 뒤, vocals 스템을 제외한 나머지 스템을 합산해 반주(Inst) 트랙을 만든다.","altTech":"Spleeter (Deezer 오픈소스 분리 모델)","affectedComponents":["separate_instrumental() 분리 엔진","_MODEL_CACHE 모델 캐시","결과 오디오 WAV 출력","requirements.txt 의존성"],"methodChange":"get_model/apply_model 호출을 Spleeter의 Separator(예: 'spleeter:4stems')로 교체하고, 텐서 기반 스템 합산·clamp 처리를 Spleeter가 내놓는 numpy 스템 합산 방식으로 바꾼다. 모델 캐시 키와 디바이스 분기 로직도 Spleeter(TensorFlow 기반) 규약에 맞춰 다시 짠다.","visualChange":"사용자 화면 흐름(드롭→진행바→완료 팝업)은 거의 같지만, 분리된 반주의 음질이 달라진다. Demucs 쪽이 보컬 잔향 제거가 더 깨끗한 편이고, Spleeter는 처리 속도가 빠른 대신 보컬 누수·고역 손실이 더 들릴 수 있다.","metrics":{"perf":70,"complexity":55,"maintain":45,"bundle":60},"tradeoff":"장점: Spleeter는 가볍고 빨라 낮은 사양·CPU 환경에서도 비교적 잘 돈다. 단점: 분리 음질(보컬 잔존·악기 선명도)이 Demucs보다 떨어지기 쉽고, TensorFlow 기반이라 기존 PyTorch CUDA 스택과 프레임워크가 달라져 환경 구성·유지보수가 갈라진다."},{"layer":"UI상태","currentTech":"HTML5 + Tailwind (CDN) + 바닐라 JS 분기","currentMethod":"index.html 정적 페이지에 Tailwind CDN 클래스로 믹싱 콘솔 UI를 그리고, 데모 모드 토글 상태에 따라 브라우저 내 가상 처리 또는 FormData로 /extract POST를 직접 분기한다. 진행바·VU 미터·완료 팝업 상태를 자바스크립트로 직접 갱신한다.","altTech":"React + 상태 관리(useState/useReducer)","affectedComponents":["믹싱 콘솔 프론트엔드 UI","데모 모드·실제 추출 분기 로직","드래그앤드롭 드롭존","진행바·VU 미터·완료 팝업"],"methodChange":"정적 HTML과 수동 DOM 갱신을 React 컴포넌트로 나누고, 데모/실제 모드·업로드 진행률·완료 상태를 컴포넌트 상태로 관리해 화면을 자동 리렌더한다. 빌드 단계(번들러)가 새로 필요해지고 CDN 한 줄 로드 방식은 사라진다.","visualChange":"최종 화면 모습은 동일하게 맞출 수 있으나, 진행바·VU 미터 같은 동적 요소의 상태 갱신이 더 매끄럽고 일관돼지고, 모드 전환 시 깜빡임·수동 갱신 누락이 줄어든다.","metrics":{"perf":60,"complexity":70,"maintain":75,"bundle":40},"tradeoff":"장점: 상태가 많아질수록(진행률·모드·결과) React가 화면-상태 동기화를 자동화해 버그가 줄고 확장·유지보수가 쉬워진다. 단점: 지금처럼 index.html 한 장으로 끝나던 구조에 빌드 도구·의존성·번들이 추가돼 초보자에겐 진입 장벽과 첫 로딩 무게가 커진다."}]},{"projectId":"jpglobal-web","enrichment":[{"area":"전체 정적 사이트 구조·페이지","tech":"HTML5","role":"사이트의 뼈대를 만들고 페이지(홈·About)를 나누며 GNB 메뉴로 페이지를 연결하는 골격 담당.","what":"글·이미지·버튼이 화면 어디에 어떤 순서로 놓일지를 글자 태그로 적어두는 설계도다. 브라우저는 이 설계도를 읽어 11개 섹션과 페이지를 화면에 펼친다.","withoutIt":"이 골격이 없으면 텍스트와 이미지가 담길 그릇 자체가 없어 화면에 아무것도 뜨지 않고, About Us 같은 다른 페이지로 넘어가는 메뉴 링크도 만들 수 없다.","example":"index.html에 Brand Promises/About/Services 등 11개 섹션을 직접 작성하고, GNB의 About Us 링크를 about.html로 연결해 현재 페이지를 is-current로 표시했다."},{"area":"색감 톤·디자인 토큰 시스템","tech":"CSS3 (custom vars)","role":"사이트 전체의 색·톤을 한곳에서 정의해두고, 시안을 통째로 갈아끼우는 색 스위치 담당.","what":"deep navy, bronze 같은 색을 이름표(변수)에 저장해두고 사이트 곳곳에서 그 이름표를 불러 쓴다. 이름표 값만 바꾸면 사이트 전체 색감이 한 번에 바뀐다.","withoutIt":"이 변수 시스템이 없으면 색을 바꿀 때마다 모든 섹션의 색 코드를 일일이 찾아 고쳐야 해서, 톤을 통째로 교체하는 다중 시안 실험이 사실상 불가능해진다.","example":"deep navy·bronze에서 → 화이트·스카이·크림 라이트 톤 → Plus X의 검정·화이트·orange 톤까지 커스텀 변수 값만 바꿔 시안을 단계별로 교체했다."},{"area":"섹션·카드 레이아웃","tech":"CSS3 (Grid)","role":"여러 장의 카드와 컬럼을 가지런한 격자로 줄 세우는 배치 담당.","what":"화면을 보이지 않는 바둑판 칸으로 나누고 카드들을 그 칸에 끼워 넣어, 3개·4개·6개씩 줄과 칸이 딱 맞게 정렬되도록 자동 배치한다.","withoutIt":"그리드가 없으면 카드들의 가로 정렬·간격을 손으로 맞춰야 해서 화면 크기가 바뀔 때마다 줄이 어긋나고 정렬이 무너지기 쉽다.","example":"Services 3카드, Projects 4카드, What We Do 6카드, Values·Reference 4카드와 5컬럼 푸터를 그리드로 가지런히 배치했다."},{"area":"풀스크린 히어로 일러스트","tech":"SVG","role":"첫 화면을 가득 채우는 부산항 그림을 코드로 그려내는 일러스트 담당.","what":"사진 파일이 아니라 선·면·색을 좌표 수식으로 그리는 그림 방식이라, 화면을 아무리 키워도 흐려지지 않고 그라데이션·색만 코드로 바꿔도 분위기가 달라진다.","withoutIt":"SVG가 없으면 무거운 이미지 파일을 써야 해 확대 시 화질이 깨지고, 톤 실험마다 그림을 새로 만들어야 해서 색감 재조정이 느려진다.","example":"부산항 컨테이너선·크레인 실루엣을 SVG로 그리고, v2에서 화이트·스카이·크림 그라데이션과 컬러풀 컨테이너 야드로 톤을 재조정했다."},{"area":"반응형·인터랙션 동작","tech":"Vanilla JS","role":"스크롤·클릭 같은 사용자 동작에 화면이 반응하도록 움직임을 넣는 동작 담당.","what":"별도 라이브러리 없이 순수 자바스크립트만으로, 스크롤하면 헤더가 따라붙고 모바일에서 메뉴가 열리며 요소가 화면에 들어올 때 스르륵 나타나게 만든다.","withoutIt":"이 동작 스크립트가 없으면 헤더 고정·모바일 메뉴·등장 애니메이션이 모두 사라져 화면이 정적인 종이처럼 멈춰 있게 된다.","example":"스티키 헤더, 모바일 nav 클론, IntersectionObserver 기반 등장 리빌을 바닐라 JS로 구현했다."},{"area":"v3 Plus X 톤 인터랙션","tech":"Vanilla JS","role":"헤더를 없앤 Plus X 톤에서 네 모서리 고정 UI·커서·시계·텍스트 등장을 직접 굴리는 고급 인터랙션 담당.","what":"마우스를 부드럽게 따라오는 점, 글자가 단어 단위로 마스크를 벗으며 드러나는 등장 효과, 좌하단에 한국 시간을 실시간으로 새기는 시계 같은 동작을 순수 자바스크립트로 매 순간 계산해 그려낸다.","withoutIt":"이 스크립트가 없으면 corner 고정 UI·풀스크린 오버레이 메뉴·단어 단위 텍스트 reveal·커서 follow dot·실시간 시계가 전부 죽어 Plus X 특유의 동적인 분위기가 사라진다.","example":"corner fixed UI 4종, 풀스크린 오버레이 nav, IntersectionObserver 단어 단위 텍스트 마스크 reveal, RAF lerp 커서 follow dot, 좌하 KST 실시간 시계를 직접 작성했다."},{"area":"v3 Plus X 톤 인터랙션","tech":"CSS3 (custom vars)","role":"다크·라이트 섹션이 번갈아 나와도 모서리 UI 색이 알아서 뒤집히게 만드는 톤 자동 대비 담당.","what":"섹션 배경이 어둡든 밝든 그 위에 얹힌 모서리 글자·아이콘 색을 자동으로 반대로 뒤집어, 어떤 배경에서도 글씨가 항상 또렷하게 보이도록 색을 처리한다.","withoutIt":"이 자동 대비가 없으면 흰 배경에 흰 글씨, 검은 배경에 검은 글씨가 겹쳐 모서리 UI가 배경에 묻혀 안 보이는 구간이 생긴다.","example":"mix-blend-mode: difference로 다크↔라이트 섹션마다 corner UI 색을 자동 invert시켜 Plus X 톤에서 모서리 UI 가독성을 유지했다."},{"area":"한글 타이포그래피","tech":"Pretendard","role":"한국어·영문 병기 글자를 깔끔하고 일관되게 보이게 하는 글꼴 담당.","what":"한글과 영문이 한 화면에 섞여도 균형 있게 읽히도록 디자인된 글꼴을, 사이트 본문·타이틀 전체에 입혀 글자 모양을 통일한다.","withoutIt":"Pretendard가 없으면 사용자 PC마다 제각각인 기본 글꼴로 보여 한글·영문 균형이 깨지고 디자인 톤의 완성도가 떨어진다.","example":"한국어·영문 병기 콘텐츠 전반에 Pretendard를 적용해 본문·타이틀 텍스트를 일관된 글꼴로 표시한다."}],"scenarios":[{"layer":"스타일","currentTech":"CSS3 (custom vars)","currentMethod":"deep navy·bronze·화이트·orange 등 색을 커스텀 변수(이름표)에 저장하고 사이트 곳곳에서 그 변수를 불러 써서, 변수 값만 바꿔 v1 deep navy → v2 라이트 → v3 Plus X 톤으로 시안을 통째로 교체한다.","altTech":"Sass/SCSS 변수 + 빌드 컴파일","affectedComponents":["색감 톤·디자인 토큰 시스템","v3 Plus X 톤 인터랙션의 mix-blend-mode 자동 invert","Capabilities 다크 밴드·푸터 등 톤이 적용되는 전 섹션"],"methodChange":"색을 브라우저가 읽는 런타임 변수 대신 SCSS 변수로 적고, 코드를 빌드(컴파일)하는 단계를 거쳐 일반 CSS로 변환한 결과물을 배포한다. 변수 정의를 별도 파일로 모아 시안별 파일로 나눌 수 있다.","visualChange":"최종 화면 색감과 톤은 동일하게 보이지만, 색을 바꾼 뒤 즉시 반영되지 않고 매번 빌드를 돌려야 결과가 나타난다. mix-blend-mode 같은 런타임 변수 의존 효과는 컴파일된 고정 값으로 바뀐다.","metrics":{"perf":70,"complexity":65,"maintain":60,"bundle":55},"tradeoff":"장점: 변수 계산·중첩·재사용 기능이 풍부해 큰 디자인 시스템을 체계적으로 관리하기 좋다. 단점: 빌드 도구 설치·실행이 필요해 지금처럼 파일만 열면 바로 도는 단순함이 사라지고, 입문자가 세팅할 일이 늘어난다."},{"layer":"UI상태","currentTech":"Vanilla JS","currentMethod":"순수 자바스크립트만으로 스티키 헤더·모바일 nav 클론·IntersectionObserver 등장 리빌, v3의 corner UI·오버레이 nav·단어 단위 텍스트 reveal·RAF 커서 dot·KST 실시간 시계를 라이브러리 없이 직접 작성한다.","altTech":"React (컴포넌트 + 상태 관리)","affectedComponents":["반응형·인터랙션 동작(스티키 헤더·모바일 nav)","v3 Plus X 톤 인터랙션(오버레이 nav·텍스트 reveal·커서 dot·시계)","전체 정적 사이트 구조(index.html·about.html)"],"methodChange":"화면을 직접 손으로 조작하는 대신, 헤더·메뉴·시계를 각각 부품(컴포넌트)으로 나누고 상태 값이 바뀌면 화면이 자동으로 다시 그려지도록 선언적으로 작성한다. 정적 HTML 두 장이 컴포넌트 트리와 빌드 결과물로 바뀐다.","visualChange":"겉보기 동작은 거의 같지만, 첫 로딩 때 자바스크립트가 화면을 그려주므로 아주 짧은 초기 지연이 생길 수 있고, 메뉴 열림·등장 효과의 전환이 상태 기반으로 더 매끄럽게 관리된다.","metrics":{"perf":55,"complexity":75,"maintain":70,"bundle":80},"tradeoff":"장점: 화면 조각이 많아지고 상태가 복잡해질수록 부품 단위로 재사용·관리하기 쉬워 규모 확장에 유리하다. 단점: 단순 정적 사이트엔 과하고, 빌드 도구와 추가 코드 무게가 붙어 번들이 커지며 입문자에겐 학습 부담이 크다."},{"layer":"시각화","currentTech":"SVG","currentMethod":"부산항 컨테이너선·크레인 실루엣을 좌표 기반 벡터(SVG)로 그리고, 그라데이션·컨테이너 야드 색을 코드로 직접 바꿔 톤을 v1 어두운 navy에서 v2 화이트·스카이·크림으로 재조정한다.","altTech":"PNG/WebP 래스터 이미지","affectedComponents":["풀스크린 히어로 일러스트","색감 톤·디자인 토큰 시스템(히어로 그라데이션 톤 연동)"],"methodChange":"그림을 코드가 아니라 그래픽 툴로 만든 그림 파일로 교체하고, 톤 시안마다 새 이미지 파일을 만들어 불러온다. 색은 CSS 변수와 직접 연동되지 않고 이미지에 구워진 상태가 된다.","visualChange":"큰 화면이나 고해상도 기기에서 확대하면 벡터와 달리 가장자리가 흐릿하게 깨질 수 있고, 톤을 바꿀 때 코드 한 줄이 아니라 이미지 자체를 새로 교체해야 한다.","metrics":{"perf":60,"complexity":35,"maintain":40,"bundle":45},"tradeoff":"장점: 복잡한 사진풍 표현이나 외부 디자인 툴 결과물을 그대로 쓰기 쉽다. 단점: 풀스크린에서 화질이 깨지고, 다중 톤 시안 실험마다 이미지를 새로 만들어야 해 지금의 빠른 색 재조정 워크플로우가 느려진다."}]},{"projectId":"us-kr-premarket","enrichment":[{"area":"프로젝트 골격·빌드","tech":"Vite","role":"Phase 1 정적 mock 대시보드의 개발 서버와 빌드 도구. 소스(src의 App·data·types·styles)를 묶어 미리보기로 배포할 dist를 만든다.","what":"코드를 고치면 화면에 즉시 반영해 주고(개발 서버), 배포할 때는 흩어진 코드·아이콘·스타일을 브라우저가 한 번에 읽을 수 있는 묶음 파일로 만들어 준다. 쉽게 말해 '작업용 작업대'이자 '포장 기계'다.","withoutIt":"코드 수정마다 수동으로 변환·새로고침해야 하고, 여러 파일을 브라우저가 읽을 수 있는 형태로 합치는 일을 직접 해야 해서 개발 속도가 크게 느려진다. 미리보기 dist도 손으로 만들어야 한다.","example":"이 프로젝트는 Codex 빌드 산출물 dist를 만들고, 그 assets 경로를 상대경로로 바꿔 project-dashboard 미리보기(/claude/previews/us-kr-premarket/)로 배포했다. npm build·typecheck·audit가 모두 PASS했다."},{"area":"프로젝트 골격·빌드","tech":"TypeScript 6","role":"골격 단계에서 코드의 타입(데이터·함수의 형태)을 검사해, 빌드 전에 typecheck로 오류를 걸러 내는 역할.","what":"프로그램이 다루는 값이 '숫자인지 글자인지 어떤 모양의 묶음인지'를 미리 적어 두게 하고, 어긋나면 실행 전에 알려 준다. 비개발자 비유로는 '서류 양식이 맞는지 제출 전에 검사해 주는 직원'이다.","withoutIt":"잘못된 데이터 모양이나 오타가 실행 중에야 드러나, 대시보드가 갑자기 빈 화면이 되거나 숫자가 엉뚱하게 표시되는 식의 런타임 오류로 이어진다. 빌드 단계 typecheck PASS 보증이 사라진다.","example":"이 프로젝트는 npm typecheck를 PASS 기준으로 두고, Vite + React 18 + TypeScript 골격으로 Phase 1 정적 대시보드를 셋업했다."},{"area":"대시보드 UI 섹션 구성","tech":"React 18","role":"대시보드의 7개 UI 섹션을 각각 독립된 화면 조각(컴포넌트)으로 만들고, mock 데이터를 그 조각에 연결(wiring)하는 역할.","what":"화면을 OverviewHero, 매크로 패널, 히트맵, 신호 테이블 같은 '부품'으로 쪼개고, 데이터가 바뀌면 해당 부품 화면만 알아서 다시 그리게 해 준다. 비개발자에게는 '레고 블록처럼 화면을 조립하는 틀'이다.","withoutIt":"화면 전체를 한 덩어리로 직접 그려야 하고, 데이터가 바뀔 때 어디를 다시 그릴지 일일이 손으로 관리해야 한다. 7개 섹션을 깔끔히 나눠 재사용·갱신하기가 어려워진다.","example":"src 아래 App·data·types·styles 구조로 OverviewHero, OvernightMacroPanel, US Theme Heatmap, Theme Detail Drawer, KRX Pre-Market Signal Table, KRX Ticker Detail Panel, Data Quality·Run Audit Panel 7개 섹션을 mock 데이터로 wiring했다."},{"area":"아이콘·시각 요소","tech":"lucide-react","role":"대시보드의 아이콘을 공급해, 다크 report-dashboard 시각 언어(near-black 배경 + paper text + orange accent)를 시각적으로 완성하는 역할.","what":"추세선·경고·시계 같은 의미를 가진 작은 그림(아이콘)을 React 화면에 바로 끼워 쓸 수 있게 해 준다. 직접 그림을 그리지 않아도 통일된 모양의 아이콘 세트를 가져다 쓰는 도구다.","withoutIt":"아이콘을 직접 이미지로 만들거나 외부에서 일일이 구해 붙여야 하고, 모양·두께·색이 제각각이 되어 다크+오렌지 통일 톤이 흐트러진다. fixed corner UI·KST clock 같은 요소의 시각적 일관성이 떨어진다.","example":"lucide-react 아이콘으로 left nav, fixed corner UI, KST clock, report footer 등을 구성해 'G.M.PARK dashboard reference'로 명시한 다크 + 오렌지 시각 언어를 맞췄다."},{"area":"한국어 UI·도움말","tech":"React 18","role":"한국어 라벨과 도움말 가이드를 각 UI 섹션 컴포넌트에 얹어, 사용자가 읽고 이해할 수 있는 한글 화면으로 만드는 역할.","what":"각 패널·테이블에 한국어 설명과 가이드 텍스트를 컴포넌트 단위로 붙여, 영문 mock 화면을 한국어 사용자가 바로 이해할 수 있게 한다. 화면 조각마다 안내 문구를 끼워 넣는 일을 담당한다.","withoutIt":"라벨·도움말을 화면 곳곳에 흩어 둔 채 관리하게 되어, 한국어 문구를 일관되게 넣고 G.M.PARK 톤으로 정렬하기 어렵다. 입문 사용자가 각 신호의 의미를 파악하기 힘들어진다.","example":"한국어 라벨과 도움말 가이드를 추가해 G.M.PARK dashboard 톤(dark + orange + corner UI)으로 정렬하고, 그 내용을 docs/PHASE1_RECEIPT.md에 영속화했다."},{"area":"공식 매크로 데이터 refresh 파이프라인","tech":"Node ESM 스크립트","role":"브라우저 밖(개발자 PC/CI)에서 외부 공식 소스를 수집하고 데이터 파일을 자동 생성하는 실행 도구. scripts/refresh-data.mjs가 그 본체.","what":"FRED·한국은행 ECOS 같은 공식 출처에서 환율·지수 값을 받아와, 화면이 그대로 읽을 수 있는 데이터 파일을 자동으로 다시 만들어 준다. 화면과 별개로 '데이터를 길어 오는 펌프' 역할의 프로그램이다.","withoutIt":"매크로 수치를 사람이 직접 찾아 손으로 코드에 적어 넣어야 하고, 출처 추적과 갱신이 어려워진다. 소스가 없을 때 missing/delayed로 표시하는 자동 안전장치도 사라져 'fake/guessed 데이터 금지' 원칙을 지키기 힘들다.","example":"scripts/refresh-data.mjs를 신설해 FRED·Bank of Korea ECOS 등 traceable 공식 소스를 우선 수집하고, USD/KRW·S&P500·Nasdaq·Dow·VIX·US 10Y를 매핑한 data.generated.ts를 자동 생성했다. 소스 미확보 시 missing/delayed로 표시한다."},{"area":"공식 매크로 데이터 refresh 파이프라인","tech":"TypeScript 6","role":"수집 스크립트가 만들어 내는 data.generated.ts를 타입이 보장된 형태로 생성·소비하게 해, UI가 안전하게 그 값을 읽도록 하는 역할.","what":"자동 생성한 데이터 파일도 '정해진 양식(타입)'에 맞는지 검사해, 환율·지수 같은 값이 올바른 모양으로 화면에 전달되도록 한다. 펌프가 길어 온 물이 규격 통에 담기는지 확인하는 셈이다.","withoutIt":"자동 생성 데이터의 필드가 어긋나거나 빠져도 빌드가 통과해, 패널이 잘못된 값을 그리거나 깨질 수 있다. missing/delayed 같은 상태값을 UI가 일관되게 다루기도 어려워진다.","example":"refresh 파이프라인이 만든 data.generated.ts를 TypeScript 타입에 맞춰 생성해, USD/KRW·S&P500·VIX 등을 각 UI 섹션이 타입 안전하게 읽도록 했다."},{"area":"정적 데이터·타입 정의","tech":"TypeScript 6","role":"Phase 1의 데이터 형태(types)를 정의하고, live provider·backend·DB 없이 mock fixture로 각 섹션을 채우는 토대 역할.","what":"각 패널이 받을 데이터의 모양을 미리 글로 적어 두고(types), 실제 서버 대신 그 모양에 맞는 가짜 예시 데이터(fixture)를 넣어 화면을 채운다. '실물 없이 양식과 견본만으로 매장을 꾸며 보는' 단계다.","withoutIt":"데이터 모양 기준이 없어 mock과 실제 데이터가 어긋날 수 있고, 나중에 라이브 연동으로 갈 때 화면을 다시 손봐야 한다. 백엔드 없이 화면을 안전하게 미리 완성하기 어렵다.","example":"Phase 1은 static fixture data 기반 mock UI만으로, live provider·backend·DB·order routing 없이 types로 데이터 형태를 정의하고 mock fixture로 7개 섹션을 채웠다."}],"scenarios":[{"layer":"UI상태","currentTech":"React 18","currentMethod":"src 아래 App·data·types·styles 구조로 7개 UI 섹션을 컴포넌트로 나누고, mock fixture 데이터를 각 컴포넌트에 wiring하며 useState로 선택/모드 상태를 관리한다.","altTech":"Svelte (SvelteKit)","affectedComponents":["OverviewHero","OvernightMacroPanel","US Theme Heatmap","Theme Detail Drawer","KRX Pre-Market Signal Table","KRX Ticker Detail Panel","Data Quality·Run Audit Panel"],"methodChange":"각 섹션을 React 함수형 컴포넌트(JSX + useState/props)로 짜던 것을 .svelte 단일 파일(템플릿 + 반응형 변수)로 옮긴다. 상태는 React state 대신 Svelte의 반응성($:)과 store로 관리하고, Theme Detail Drawer 같은 선택 상태도 store 구독으로 바뀐다. mock fixture를 props로 내려주는 구조는 비슷하게 유지된다.","visualChange":"다크 + 오렌지 시각 언어와 7개 섹션 레이아웃 자체는 거의 그대로 보인다. 사용자가 보는 화면 차이는 미미하지만, 드로어 열림·테이블 선택 같은 상호작용이 살짝 더 가볍고 빠르게 반응할 수 있다.","metrics":{"perf":80,"complexity":55,"maintain":60,"bundle":35},"tradeoff":"장점: 번들이 가볍고 런타임이 빨라, 정적 mock 대시보드처럼 단순한 화면엔 잘 맞는다. 단점: React 18 + lucide-react 생태계와 'G.M.PARK dashboard reference' 컴포넌트 자산을 버리고 7개 섹션을 전부 다시 써야 하며, 입문자가 참고할 React 자료·아이콘 호환성이 줄어든다."},{"layer":"데이터","currentTech":"Node ESM 스크립트 (scripts/refresh-data.mjs) + TypeScript","currentMethod":"빌드 타임에 Node 스크립트가 FRED·한국은행 ECOS 등 공식 소스를 수집해 data.generated.ts를 자동 생성하고, UI는 그 정적 파일을 읽는다. 소스 미확보 시 missing/delayed로 표시한다. 라이브 provider·backend·DB는 없다.","altTech":"브라우저 런타임 fetch (클라이언트에서 공개 API 직접 호출)","affectedComponents":["OvernightMacroPanel","Data Quality·Run Audit Panel","scripts/refresh-data.mjs","data.generated.ts"],"methodChange":"빌드 시점에 데이터를 미리 굽는 대신, 대시보드가 열릴 때 브라우저가 직접 공식 API를 호출해 USD/KRW·S&P500·VIX 등을 가져온다. refresh-data.mjs와 data.generated.ts는 사라지고, OvernightMacroPanel이 로딩·에러·missing/delayed 상태를 직접 처리한다. CORS·API 키·요청 한도 같은 런타임 제약을 코드로 감당해야 한다.","visualChange":"값이 빌드에 고정되지 않고 페이지를 열 때마다 갱신되어, 매크로 패널에 로딩 스피너와 '방금 갱신됨' 같은 시점 표시가 새로 생긴다. 다만 호출 실패 시 빈 패널·지연이 사용자에게 그대로 노출될 위험이 커진다.","metrics":{"perf":45,"complexity":70,"maintain":50,"bundle":55},"tradeoff":"장점: 빌드 없이도 최신 매크로 값을 보여줄 수 있어 '항상 최신'에 가까워진다. 단점: 출처 추적·검증을 빌드에서 일괄로 하던 traceable 파이프라인이 약해지고, 'fake/guessed 데이터 금지' 원칙을 런타임에서 지키기 더 까다로우며, Phase 1의 정적 mock·연구 전용 안전 경계와 어긋날 수 있다."},{"layer":"스타일","currentTech":"lucide-react","currentMethod":"lucide-react 아이콘 컴포넌트로 left nav·fixed corner UI·KST clock·report footer 등의 아이콘을 채워 다크 report-dashboard 시각 언어를 구성한다.","altTech":"직접 만든 SVG 아이콘 세트 (인라인 SVG 컴포넌트)","affectedComponents":["left nav 아이콘","fixed corner UI","KST clock","report footer","US Theme Heatmap 범례 아이콘"],"methodChange":"라이브러리에서 아이콘을 import 해 쓰던 것을, 필요한 아이콘만 직접 그린 인라인 SVG 컴포넌트로 대체한다. 아이콘 추가·수정 때마다 SVG 패스를 직접 관리해야 하고, 색·두께를 다크+오렌지 톤에 맞춰 수작업으로 통일한다.","visualChange":"잘 만들면 화면은 거의 같아 보이지만, 아이콘 모양·두께의 통일감이 사람 손에 달리게 된다. 커스텀 모양(예: KRX/프리마켓 전용 기호)을 더 자유롭게 넣을 수 있는 대신, 누락·불일치가 생기기 쉽다.","metrics":{"perf":70,"complexity":60,"maintain":45,"bundle":75},"tradeoff":"장점: 외부 의존성이 빠져 번들에서 안 쓰는 아이콘 무게가 사라지고, 프로젝트 고유 기호를 마음대로 만들 수 있다. 단점: 통일된 아이콘 세트와 입문자 친화적 사용법을 잃고, 아이콘마다 직접 그리고 톤을 맞추는 유지보수 부담이 커진다."}]},{"projectId":"knowledge","enrichment":[{"area":"지구 지도 (공급망 모드 전용)","tech":"Three.js","role":"공급망 모드에서 기업 본사 핀이 얹히는 3D 지구본 본체를 그리는 렌더링 엔진","what":"구(球) 모양 도형에 8K 낮/밤 텍스처와 노멀맵을 입혀 진짜 지구처럼 보이는 입체 공을 만들고, 화면에 실시간으로 그려준다. 확대해도 흐려지지 않도록 텍스처 선명도(anisotropy)를 16으로 높였다.","withoutIt":"3D 지구본을 화면에 띄울 방법 자체가 사라진다. 기업 본사를 실제 위치에 핀으로 꽂거나 대륙 위에 회사를 배치하는 시각화가 불가능해지고, 공급망 모드의 핵심 무대가 통째로 빠진다.","example":"Earth.tsx에서 sphereGeometry에 solarsystemscope CC-BY 텍스처를 입혀 meshStandardMaterial로 지구본을 그리고, 본사 핀이 대륙과 정확히 맞도록 자전·축기울기 없이 정적으로 고정한다."},{"area":"지구 지도 (공급망 모드 전용)","tech":"@react-three/fiber","role":"Three.js 지구본을 React 컴포넌트(Earth.tsx)로 선언적으로 다루게 해주는 연결층","what":"원래 명령형으로 한 줄씩 짜야 하는 Three.js 3D 코드를, React에서 화면 부품을 조립하듯 컴포넌트로 작성할 수 있게 바꿔준다. 지구·핀·텍스처 같은 3D 요소를 JSX 태그처럼 다룰 수 있다.","withoutIt":"3D 장면과 React UI(패널·토글)가 따로 놀아, 상태가 바뀔 때 지구 화면을 갱신하는 코드를 전부 수작업으로 이어붙여야 한다. 모드 전환 같은 React 상태 변화가 3D에 자동 반영되지 않는다.","example":"useTexture 훅으로 낮/밤 텍스처와 노멀맵을 불러와 Earth.tsx 컴포넌트 안에서 지구본을 선언적으로 구성한다."},{"area":"지구 지도 (공급망 모드 전용)","tech":"@react-three/drei","role":"지구 대기광 같은 고급 3D 효과를 손쉽게 쓰도록 해주는 헬퍼 모음","what":"3D 장면에 자주 쓰는 기능(셰이더 머티리얼, 라이트 등)을 미리 만들어 둔 도구 상자다. 지구 가장자리가 푸르게 빛나는 대기광(프레넬 림) 같은 효과를 직접 셰이더를 다 짜지 않아도 붙일 수 있게 돕는다.","withoutIt":"대기광 같은 효과를 GLSL 셰이더로 처음부터 손수 구현해야 해서 작업량이 크게 늘고, 지구본이 밋밋한 공처럼 보여 실사감이 떨어진다.","example":"shaderMaterial로 만든 GLSL 프레넬 림을 지구 외곽에 가산해, 지구 가장자리에 푸른 대기광 띠를 둘러 사실적으로 보이게 한다."},{"area":"칩 분류 — 카툰 배경 + 실사풍 3D 아이콘 그리드","tech":"Three.js","role":"카테고리별 실사풍 3D 칩 모델과 카툰 배경 구면을 그리는 시각화 엔진","what":"IC 패키지·메모리 DIMM·전력 트랜지스터·웨이퍼 같은 반도체 부품을 진짜 제품처럼 보이는 3D 모델로 만들어, 금속 질감(PBR 재질)으로 비스듬한 시점에서 보여준다.","withoutIt":"칩 분류 모드가 평면 아이콘이나 글자 목록 수준으로 떨어진다. 각 반도체 종류를 실제 부품 모양으로 입체적으로 보여주는 「칩 박물관」 같은 경험이 사라진다.","example":"CategoryNode.tsx가 IC 패키지·DIMM·SOIC·TO-247 전력·카메라 렌즈·FPGA 셀격자·실리콘 웨이퍼 등을 PBR 재질 3/4 시점으로 그려 패밀리별 행 그리드로 정렬한다."},{"area":"칩 분류 — 카툰 배경 + 실사풍 3D 아이콘 그리드","tech":"@react-three/drei","role":"3D 칩 모델이 금속처럼 반사되도록 조명 환경을 깔아주는 도구","what":"실제 스튜디오 조명처럼 주변광(IBL)을 만들어, 금속 칩 표면에 빛이 반사돼 입체감이 살아나게 한다. 또 3D 위에 HTML 라벨을 겹쳐 띄우는 기능도 제공한다.","withoutIt":"칩 모델이 빛 반사 없이 평평하고 플라스틱처럼 보여 「실사풍」이라는 핵심 느낌이 사라진다. 3D 위에 텍스트 라벨을 얹기도 번거로워진다.","example":"drei Environment(Lightformer)로 IBL 조명을 깔아 금속 칩이 반사돼 입체로 보이게 하고, Html 라벨은 pointer-events:none으로 띄운다."},{"area":"공급망 앰블럼 — 클릭 시 본사 핀·확대","tech":"simple-icons","role":"기업 노드에 표시할 실제 회사 로고/워드마크의 출처","what":"수많은 브랜드의 공식 로고를 모아둔 무료 아이콘 모음이다. 여기서 회사 로고를 가져와 공급망 화면의 기업 노드에 진짜 회사 마크를 띄운다.","withoutIt":"기업 노드가 그냥 동그라미나 글자 이름표 수준이 되어, 어떤 회사인지 한눈에 알아보기 어렵다. 브랜드 식별성이 크게 떨어진다.","example":"CompanyEmblem.tsx가 simple-icons 로고/워드마크를 CanvasTexture 배지로 만들어 기업 노드로 띄운다(이전 라운드에서 8개사 적용)."},{"area":"공급망 앰블럼 — 클릭 시 본사 핀·확대","tech":"@react-three/drei","role":"기업 로고 배지가 항상 카메라를 정면으로 바라보게 하는 빌보드 기능 제공","what":"3D 공간에 떠 있는 로고 배지가 어느 각도에서 봐도 늘 화면을 정면으로 향하도록 자동 회전시킨다(빌보드). 덕분에 회사 로고가 뒤집히거나 옆으로 누워 안 보이는 일이 없다.","withoutIt":"카메라를 돌리면 로고 배지가 옆으로 돌아가 납작하게 보이거나 안 보이게 된다. 회사 식별이 시점에 따라 들쭉날쭉해진다.","example":"simple-icons로 만든 CanvasTexture 배지를 drei Billboard로 띄워, 회사 클릭 시 본사 위경도로 지구 위에 핀되며 확대되고 무관한 회사는 페이드아웃한다."},{"area":"공급망 관계 — 지구 위 호(arc)","tech":"Three.js","role":"기업 간 공급 관계를 지구 표면을 따라 흐르는 곡선 화살표로 그리는 엔진","what":"두 회사 본사 좌표 사이를, 지구 표면에 밀착한 부드러운 곡선(대권)으로 잇고 끝에 화살촉을 달아 「누가 누구에게 공급하는지」 방향을 보여준다.","withoutIt":"기업 사이의 공급·납품 관계를 시각적으로 표현할 길이 없어진다. 회사들이 점으로만 흩어져 있고 그들 사이의 연결고리가 보이지 않는다.","example":"SupplyArrow.tsx가 회사 클릭 시 연계된 엣지만 본사 좌표 사이를 great-circle 곡선 TubeGeometry로 잇고 도착지 coneGeometry 화살촉과 연계 기업명 라벨을 붙인다."},{"area":"공급망 벡터 지도 + 지명 라벨","tech":"earcut","role":"국가·주·도시 경계 데이터를 3D로 색칠할 수 있는 삼각형 조각으로 쪼개는 도구","what":"지도의 나라 모양 같은 복잡한 다각형을, 컴퓨터가 그릴 수 있는 잘게 쪼갠 삼각형들로 변환한다(삼각분할). 이 삼각형들을 구면에 맞춰 채워 단색 카툰 지도를 만든다.","withoutIt":"래스터(사진) 지도를 그대로 써야 하는데, 그러면 확대할 때마다 지도가 흐려지고 깨진다. 벡터 지도의 「무한 확대해도 선명함」을 얻을 수 없다.","example":"Natural Earth 국가/주/도시 GeoJSON을 earcut으로 구면 적응 삼각분할해 단색 카툰색 폴리곤으로 채우고, 그 위에 국경·격자 라인을 그린다."},{"area":"공급망 벡터 지도 + 지명 라벨","tech":"troika-three-text","role":"지도 위 국가·주·도시 이름표를 또렷하게 띄우는 3D 텍스트 렌더러","what":"3D 지도 위에 글자를 선명하게(SDF 방식) 그려주는 도구다. 카메라가 멀고 가까움에 따라 어떤 지명을 보여줄지 단계별로 조절하고, 글자가 늘 정면을 보게 한다.","withoutIt":"지도에 지명 라벨을 넣기 어렵거나, 넣어도 확대 시 글자가 뭉개진다. 어느 나라·도시인지 식별이 안 되고 화면이 과밀해진다.","example":"국가/주/도시 지명을 troika-three-text(SDF) 빌보드 라벨로 만들어, 카메라 거리에 따라 보여줄 지명을 LOD로 가리고 전면 컬링해 표시한다."},{"area":"공급망 벡터 지도 + 지명 라벨","tech":"Natural Earth","role":"지도를 그리는 데 쓰는 국가/주/도시 경계 좌표 원본 데이터","what":"전 세계 나라·주·도시의 경계선을 좌표로 정리한 공개 지리 데이터다. 이 데이터가 있어야 지도의 나라 모양과 도시 위치를 정확히 그릴 수 있다.","withoutIt":"지도의 형태(국경선·행정경계·도시 위치)를 만들 근거 데이터가 없어 벡터 지도를 그릴 수 없다. 본사 핀을 정확한 위치에 꽂을 기준도 사라진다.","example":"Natural Earth GeoJSON을 earcut으로 삼각분할해 단색 폴리곤으로 채우고, 같은 데이터의 도시 좌표에 troika 지명 라벨을 단다."},{"area":"카메라·인터랙션·배치","tech":"@react-three/drei","role":"드래그 회전·휠 줌 등 사용자가 3D 장면을 직접 조작하는 카메라 컨트롤 제공","what":"마우스로 화면을 돌리고 휠로 확대/축소하는 카메라 조작(OrbitControls)을 손쉽게 붙여준다. 움직임이 부드럽게 감속(댐핑)되도록 하고, 자동 회전 없이 사용자 조작 위주로 둔다.","withoutIt":"사용자가 3D 우주/지구를 직접 돌리거나 확대할 수 없어 시각화가 멈춰 있는 그림이 된다. 칩이나 회사를 들여다보는 탐색 경험이 사라진다.","example":"Scene.tsx의 OrbitControls를 자동회전 없이 댐핑·줌만 두고, 휠/드래그 시 fly-to를 즉시 중단해 휠 줌이 항상 작동하도록(고정 방지) 설정한다."},{"area":"UI 패널·범례·모드 토글","tech":"React","role":"모드·선택 상태를 관리하고 화면 부품(패널·토글·범례)을 배치하는 UI 골격","what":"칩 분류/공급망 모드 전환, 무엇을 선택했는지 같은 화면 상태를 기억하고, 그에 맞춰 패널과 버튼을 자동으로 다시 그려준다. 화면을 부품 단위로 조립한다.","withoutIt":"모드 전환이나 선택에 따라 화면이 바뀌는 인터랙티브 UI를 만들 수 없다. 상태가 바뀔 때마다 어떤 부분을 다시 그릴지 일일이 손으로 처리해야 한다.","example":"App.tsx가 React useState로 모드·선택 상태를 관리하며 ViewToggle·Legend를 배치하고, 상태 변화에 맞춰 InfoPanel 등 UI를 갱신한다."},{"area":"UI 패널·범례·모드 토글","tech":"framer-motion","role":"상세 패널이 부드럽게 슬라이드되며 나타나는 애니메이션을 담당","what":"패널이 갑자기 툭 나타나지 않고 옆에서 미끄러져 들어오거나 사라지는 부드러운 움직임을 만들어준다. 등장·퇴장 전환을 자연스럽게 처리한다.","withoutIt":"패널이 즉시 켜졌다 꺼지듯 딱딱하게 나타나 사용 경험이 거칠어진다. 부드러운 전환 효과를 손수 구현해야 한다.","example":"InfoPanel.tsx가 framer-motion의 AnimatePresence와 motion.aside 스프링 트랜지션으로 상세 패널을 슬라이드 인하고 글래스 스타일을 입힌다."},{"area":"UI 패널·범례·모드 토글","tech":"Tailwind","role":"패널·범례 등 UI 요소의 글래스 스타일과 레이아웃을 만드는 CSS 유틸리티","what":"미리 정의된 짧은 클래스 이름만 붙여 색·여백·둥근 모서리·반투명 유리 느낌 같은 스타일을 빠르게 입힌다. 별도 CSS 파일을 길게 쓰지 않아도 된다.","withoutIt":"UI 스타일을 일일이 손으로 CSS를 써서 맞춰야 해 작업이 느려지고 디자인 일관성이 흐트러진다.","example":"InfoPanel 등에 Tailwind 유틸 클래스로 글래스 스타일(반투명·블러)을 입혀 상세 패널을 꾸민다."},{"area":"빌드·타입·배포 환경","tech":"Vite","role":"개발 서버 실행과 배포용 번들을 만드는 빌드 도구","what":"코드를 짤 때 즉시 화면에 반영되는 개발 서버를 띄우고, 배포할 때는 여러 파일을 압축·정리한 번들로 묶어준다. 개발과 출시 양쪽을 빠르게 돌린다.","withoutIt":"개발 중 변경을 빠르게 확인하기 어렵고, 배포용으로 코드를 묶고 최적화하는 과정을 수동으로 처리해야 한다.","example":"package.json에서 dev는 vite로 띄우고, build는 tsc -b로 타입체크한 뒤 vite build로 번들링해 타입검사와 빌드를 함께 돌린다."},{"area":"빌드·타입·배포 환경","tech":"TypeScript","role":"데이터 구조와 컴포넌트 Props에 타입을 붙여 오류를 빌드 단계에서 잡는 언어","what":"변수와 함수가 어떤 모양의 데이터를 주고받는지 미리 약속(타입)을 정해, 잘못된 데이터가 들어가면 실행 전에 경고해준다. 영역 데이터처럼 구조가 복잡한 프로젝트의 실수를 줄인다.","withoutIt":"잘못된 데이터 형태로 인한 버그를 실제 실행해서 깨질 때까지 모른다. 영역이 늘어날수록 데이터 구조 실수가 쌓여 유지보수가 어려워진다.","example":"전 컴포넌트를 타입드 Props로 작성하고, build 시 tsc -b로 타입체크를 강제해 AtlasArea 등 데이터 구조의 오류를 사전에 차단한다."},{"area":"빌드·타입·배포 환경","tech":"@fontsource","role":"Inter 폰트를 외부 호출 없이 프로젝트 안에 직접 담는 self-host 폰트 패키지","what":"구글 폰트 서버에 매번 접속하지 않고, 폰트 파일을 프로젝트 안에 포함시켜 쓰게 해준다. 인터넷 외부 호출 없이 글꼴이 로드된다.","withoutIt":"폰트를 받으려 외부 서버에 접속해야 해 로딩이 외부 환경에 의존하고, 런타임 외부 호출 0이라는 자체 완결성 목표를 지킬 수 없다.","example":"폰트는 @fontsource로 Inter를 self-host하고, Earth.tsx는 import.meta.env.BASE_URL로 서브패스 배포에 대응한다."},{"area":"멀티영역 아키텍처 (Knowledgeverse)","tech":"TypeScript","role":"한 지식 영역 전체를 하나의 데이터 규격(AtlasArea 인터페이스)으로 정의하는 설계 토대","what":"반도체·전력 같은 각 지식 영역을 「분류·기업·공급망·색·본사좌표」를 담은 똑같은 모양의 데이터 묶음으로 정의한다. 그래서 3D 엔진은 영역이 무엇이든 데이터만 바꿔 끼우면 돌아간다.","withoutIt":"영역마다 화면 코드를 새로 짜야 해 영역을 수십·수백 개로 늘린다는 목표가 불가능해진다. 데이터 규격이 들쭉날쭉해 새 영역 추가가 위험해진다.","example":"AtlasArea 인터페이스 하나로 한 영역을 표현하고 data/areas/에 영역 모듈을 추가해 레지스트리(AREAS[])에 등록만 하면 영역이 늘어난다(현재 반도체·전력·2차전지·디스플레이·철강·제련 5영역)."},{"area":"멀티영역 아키텍처 (Knowledgeverse)","tech":"React","role":"영역 선택기와 데이터 주도 3D/UI를 연결해 영역 전환을 처리하는 UI 계층","what":"좌상단 드롭다운에서 영역을 고르면, 그에 맞는 영역 데이터를 화면 부품에 prop으로 넘겨 3D 장면과 UI 전체를 그 영역으로 갈아끼운다.","withoutIt":"영역을 전환하는 인터랙티브 선택기를 만들 수 없고, 선택한 영역 데이터를 화면 곳곳에 자동 반영하기 어려워진다.","example":"3D 엔진/UI를 area prop으로 구동하고, 좌상단 AreaSelector 드롭다운으로 영역을 전환하며 companyLayout 좌표 계산은 영역 데이터를 인자로 받는 순수함수로 일반화했다."},{"area":"전력 유니버스 — 카툰 대한민국 지도 (세계지도 없음)","tech":"react-spring","role":"한반도 17개 시도가 통통 튀어 오르며 조립되듯 등장하는 물리 기반 애니메이션 담당","what":"지도의 각 시도가 자기 위치에서 아래에서 위로 탄력 있게 튀어 오르며 나타나도록 자연스러운 「용수철」 움직임을 만든다. 시간차(스태거)를 둬 지도가 조립되는 느낌을 준다.","withoutIt":"지도가 한 번에 정적으로 나타나 밋밋해진다. 시도가 차례로 통통 튀며 조립되는 인상적인 등장 연출이 사라진다.","example":"KoreaCartoonMap에서 각 시도가 config.wobbly와 스태거 delay로 아래→위로 튀어 오르고, animated 머티리얼 opacity로 페이드인하며 지도가 조립되듯 등장한다."},{"area":"전력 유니버스 — 카툰 대한민국 지도 (세계지도 없음)","tech":"southkorea-maps","role":"대한민국 17개 광역시도 경계를 그리는 한국 지도 GeoJSON 데이터","what":"대한민국 행정구역(시도·시군구)의 경계선을 좌표로 담은 데이터다. 전력 영역에서 지구본 대신 한반도만 정확한 모양으로 그릴 수 있게 해준다.","withoutIt":"전력 영역의 한반도 카툰 지도를 그릴 근거 데이터가 없다. 전력 기업을 시도 위 실제 위치에 박을 좌표 기준도 사라진다.","example":"southkorea-maps GeoJSON으로 17개 광역시도를 earcut 삼각분할해 파스텔 카툰색으로 채우고, 같은 좌표계라 기업이 시도 위 실제 위치에 박힌다."},{"area":"전력 유니버스 — 카툰 대한민국 지도 (세계지도 없음)","tech":"earcut","role":"한반도 시도 다각형을 색칠 가능한 삼각형으로 쪼개는 삼각분할 도구","what":"시도 경계 같은 복잡한 다각형을 컴퓨터가 채워 그릴 수 있는 삼각형들로 변환한다. 이 삼각형을 파스텔색으로 채워 카툰 지도를 완성한다.","withoutIt":"한반도 시도 영역을 면으로 채워 칠할 수 없어, 카툰풍 색면 지도를 만들 수 없다.","example":"southkorea-maps의 17개 광역시도 GeoJSON을 earcut으로 삼각분할한 뒤 파스텔 카툰색으로 채우고 다크 외곽선을 입힌다."},{"area":"구글어스식 도시 딥줌 — 행정구(시군구) LOD","tech":"Three.js","role":"카메라 거리에 따라 시군구 경계가 페이드인하는 딥줌 LOD를 그리는 엔진","what":"기업을 클릭하면 카메라가 본사 도시까지 깊게 날아 들어가고(구글어스식), 가까워질수록 시군구(251개) 경계가 서서히 나타난다. 멀면 시도만 보이고 가까우면 어느 구인지 드러난다.","withoutIt":"공급망 지도가 시도 수준에서 멈춰, 기업이 정확히 어느 구·시에 있는지 깊이 들여다보는 「구글어스식」 탐색이 불가능해진다.","example":"카메라 거리(LOD)에 따라 시군구 경계를 페이드인하되, 경계는 피처 전체를 단일 라인 지오메트리로 병합해 한 번에 그리고 near plane·minDistance를 낮춰 더 깊이 확대한다."},{"area":"구글어스식 도시 딥줌 — 행정구(시군구) LOD","tech":"southkorea-maps","role":"딥줌 시 나타나는 시군구(행정구 251개) 경계 데이터 출처","what":"광역시도보다 더 세밀한 시군구 단위 경계 좌표를 제공한다. 카메라가 도시로 줌인했을 때 보여줄 행정구 경계선의 원본 데이터다.","withoutIt":"줌인했을 때 보여줄 세부 행정구 경계가 없어, 딥줌해도 어느 구에 있는지 구분되지 않는다.","example":"southkorea-maps의 시군구(251개) 경계를 카메라가 깊게 들어왔을 때 페이드인하고, 시군구 영문 라벨은 화면 중앙 좁은 콘 안의 것만 거리 비례로 표시해 과밀을 막는다."},{"area":"반도체 8대 공정 — 3D 웨이퍼 파이프라인 (공정 과정 모드)","tech":"Three.js","role":"8대 공정 8단계를 뱀형 흐름의 3D 파이프라인으로 그리는 시각화 엔진","what":"반도체 만드는 8단계(웨이퍼 제조·산화·포토·식각·증착·금속배선·테스트·패키징)를 구불구불한 흐름으로 늘어놓고, 단계마다 그 공정을 상징하는 고유한 3D 비주얼을 절차적으로 그려준다.","withoutIt":"공정 과정 모드가 평범한 텍스트 인포그래픽으로 남는다. 각 제조 단계를 입체적으로 보여주고 클릭해 들여다보는 3D 학습 경험이 사라진다.","example":"ProcessFlow.tsx가 8단계를 serpentine(뱀형) 흐름으로 배치하고 단계 사이를 TubeGeometry+cone 화살표로 잇되, 단계마다 실리콘 웨이퍼 다이격자·식각 트렌치+플라즈마 글로우·완성 IC 패키지 같은 고유 3D 비주얼을 입힌다."},{"area":"반도체 8대 공정 — 3D 웨이퍼 파이프라인 (공정 과정 모드)","tech":"@react-three/drei","role":"공정 단계 클릭 줌인과 패널 연동 등 인터랙션을 돕는 헬퍼","what":"각 공정 단계를 클릭하면 카메라가 그 단계로 줌인하고 옆에 설명 패널이 열리는 인터랙션을 손쉽게 구성하도록 돕는 도구 모음이다.","withoutIt":"단계 클릭 시 카메라 이동·정보 패널 연동을 처음부터 다 짜야 해 작업량이 늘고, 8대 공정을 단계별로 파고드는 학습 흐름이 매끄럽지 못해진다.","example":"단계를 클릭하면 카메라가 줌인하고 우측 패널에 「왜 중요한가·특징·국내 기업·해외 기업」이 열리며, AtlasArea.process 데이터로 구동돼 다른 영역에는 영향이 없다."}],"scenarios":[{"layer":"시각화","currentTech":"Three.js + @react-three/fiber (지구본 sphereGeometry + 8K 텍스처 meshStandardMaterial)","currentMethod":"공급망 모드에서 구 도형에 8K 낮/밤 텍스처와 노멀맵을 입혀 3D 지구본을 그리고, 그 표면에 기업 본사를 위경도 좌표로 핀하고 great-circle 호로 관계를 잇는다.","altTech":"2D 지도 라이브러리 (예: 평면 SVG/Canvas 세계지도에 좌표 투영)","affectedComponents":["Earth.tsx (지구본 렌더링)","CompanyEmblem.tsx (본사 핀·확대)","SupplyArrow.tsx (지구 위 호 관계)","카메라·OrbitControls (Scene.tsx)"],"methodChange":"3D 구면 텍스처·셰이더 대신 평면 지도 위에 위경도를 화면 좌표로 투영해 본사 핀을 찍고, 곡선 호 대신 평면상 곡선/직선으로 관계를 그린다. OrbitControls의 3D 궤도 회전은 2D 패닝·줌으로 단순화된다.","visualChange":"빙글 돌릴 수 있는 입체 지구본과 가장자리 대기광이 사라지고, 위에서 내려다보는 평평한 지도가 된다. 본사 핀과 관계 호는 그대로지만 「우주 속 지구」 같은 몰입감과 3/4 시점 입체감이 사라진다.","metrics":{"perf":78,"complexity":40,"maintain":65,"bundle":55},"tradeoff":"장점 — 8K 텍스처와 셰이더가 빠져 가볍고 빠르며, 2D 좌표 투영은 3D 구면 계산보다 다루기 쉬워 초보자가 이해하기 쉽다. 단점 — 회전하는 입체 지구본 특유의 몰입감과 대기광 연출이 사라지고, 전력 영역의 한반도 딥줌처럼 3D로 통일된 시각 언어가 영역마다 깨질 수 있다."},{"layer":"스타일","currentTech":"Tailwind + framer-motion (UI 패널·범례·모드 토글)","currentMethod":"InfoPanel을 Tailwind 유틸 클래스로 글래스 스타일링하고, framer-motion의 AnimatePresence·motion.aside 스프링 트랜지션으로 패널을 부드럽게 슬라이드 인/아웃한다.","altTech":"순수 CSS (CSS 클래스 + CSS transition/keyframes)","affectedComponents":["InfoPanel.tsx (상세 패널 슬라이드)","Legend / ViewToggle (범례·모드 토글)","App.tsx (UI 배치)"],"methodChange":"Tailwind 유틸 클래스를 직접 작성한 CSS 클래스로 바꾸고, framer-motion의 스프링 애니메이션을 CSS transition과 @keyframes로 대체한다. 등장·퇴장 타이밍을 라이프사이클에 맞춰 클래스 토글로 수동 제어해야 한다.","visualChange":"패널의 글래스 느낌과 슬라이드 인 동작은 비슷하게 재현할 수 있지만, framer-motion의 물리 기반 스프링 감속이 일정한 CSS easing으로 바뀌어 미세하게 덜 자연스러워진다. 등장·퇴장 전환이 약간 더 기계적으로 느껴질 수 있다.","metrics":{"perf":72,"complexity":58,"maintain":50,"bundle":80},"tradeoff":"장점 — framer-motion·Tailwind 의존성이 빠져 번들이 줄고, 외부 라이브러리 없이 CSS만으로 돌아가 자체 완결성이 높아진다. 단점 — 스프링 같은 자연스러운 모션과 등장/퇴장 자동 처리를 손수 구현해야 해 코드가 늘고, 유틸 클래스의 빠른 스타일링 편의를 잃어 디자인 일관성 유지가 더 번거롭다."}]},{"projectId":"tradelogix","enrichment":[{"area":"상태머신·렌더 엔진","tech":"Vanilla JS","role":"통관유형·항만·Incoterm·활성 신고필증 필드를 하나로 묶은 중앙 상태 객체를 관리하고, 상태가 바뀔 때마다 화면을 다시 그리는 두뇌 역할.","what":"사용자가 '수입/수출/반송', '북항/신항' 같은 선택을 누르면 그 선택을 단일 상태 객체에 기록하고, setState→render 단방향 루프로 관련 패널만 다시 그린다. React 같은 프레임워크 없이 순수 자바스크립트로 이 흐름을 직접 만든다.","withoutIt":"선택값을 저장하고 화면을 갱신할 주체가 없어, 통관유형을 바꿔도 플로우차트·게이지·신고필증이 따로 놀거나 갱신되지 않는다. 화면 곳곳의 상태가 어긋나 동기화가 깨진다.","example":"'반송' 통관유형을 클릭하면 상태 객체의 통관유형이 바뀌고, 그 한 번의 setState로 보세창고 플로우차트(5단계)와 신고필증 패널이 동시에 반송 기준으로 다시 렌더된다."},{"area":"보세창고 프로세스 플로우차트","tech":"SVG","role":"부산항 북항·신항의 보세창고 노드와 통관 흐름선을 해상도에 상관없이 선명하게 그리는 벡터 드로잉 레이어.","what":"세방·동방 우암물류·BPA(북항), HJNC 배후물류단지·DWL글로벌·BIDC(신항) 같은 보세창고를 인라인 SVG 도형으로 그려 플로우차트를 만든다. 벡터라 확대해도 깨지지 않는다.","withoutIt":"이미지(PNG)로 대체하면 확대 시 흐려지고, 노드별 클릭 영역을 잡거나 동적으로 색·상태를 바꾸기가 어려워 인터랙티브 플로우차트를 만들 수 없다.","example":"신항을 선택하면 HJNC 배후물류단지·세방부산신항물류센터 등의 보세창고 노드가 SVG로 그려지고, 노드를 클릭하면 관세법 이론 vs 부산항 실무·리스크 스플릿 뷰가 뜬다."},{"area":"보세창고 프로세스 플로우차트","tech":"Vanilla JS","role":"SVG 노드의 클릭 이벤트를 받아 이론/실무 스플릿 뷰포트를 동적으로 만들어 끼우는 인터랙션 처리기.","what":"SVG로 그려진 보세창고 노드에 클릭 이벤트를 붙이고, 클릭하면 관세법 이론과 부산항 실무·리스크를 좌우로 나눈 뷰포트를 자바스크립트로 생성·렌더한다.","withoutIt":"SVG 그림은 그려지지만 클릭해도 아무 반응이 없는 정적 그림이 된다. 노드를 눌러 이론·실무 비교를 펼치는 학습 인터랙션이 사라진다.","example":"북항의 'BPA 지정보세창고' 노드를 클릭하면 자바스크립트가 좌측 관세법 이론, 우측 부산항 실무·리스크로 나뉜 스플릿 뷰포트를 렌더한다."},{"area":"Incoterms 2020 매트릭스·분기점 게이지","tech":"SVG","role":"Incoterms 11규칙 그리드와 매도인→매수인 축의 비용·위험 분기점 마커를 그리는 벡터 게이지 시각화.","what":"Multimodal 7 + Maritime 4, 총 11개 Incoterms 규칙을 그리드로 배치하고, 매도인에서 매수인으로 이어지는 축 위에 비용 분기점과 위험 분기점을 SVG 마커로 표시한다.","withoutIt":"비용·위험이 어디서 매수인으로 넘어가는지를 정확한 위치의 마커로 보여줄 수 없어, C-텀에서 '비용 분기점≠위험 분기점'이라는 핵심 개념을 시각적으로 전달하기 어렵다.","example":"CIF를 클릭하면 비용 분기점은 목적항까지, 위험 분기점은 선적항 본선 적재 시점으로 서로 다른 위치에 SVG 마커가 찍혀 둘이 분리됨을 한눈에 보여준다."},{"area":"Incoterms 2020 매트릭스·분기점 게이지","tech":"Vanilla JS","role":"11규칙 그리드의 클릭을 감지해 선택된 Incoterm의 게이지를 다시 계산·렌더하는 로직.","what":"사용자가 11개 규칙 중 하나를 클릭하면 상태에 선택 Incoterm을 기록하고, 그 규칙에 맞는 비용·위험 분기점 위치를 계산해 게이지 마커를 갱신한다.","withoutIt":"규칙을 눌러도 게이지가 바뀌지 않아, 모든 Incoterm이 같은 그림으로 보인다. 규칙별 비용·위험 차이를 비교하는 기능이 동작하지 않는다.","example":"EXW에서 DDP로 클릭을 옮기면 자바스크립트가 분기점을 재계산해, 매도인 부담이 거의 없는 EXW에서 매도인이 거의 다 부담하는 DDP로 마커가 크게 이동한다."},{"area":"수입신고필증 인스펙터","tech":"Tailwind CSS","role":"한국 수입신고필증 양식의 칸·격자 레이아웃을 유틸리티 클래스로 빠르게 재현하는 스타일 레이어.","what":"실제 수입신고필증 서식을 Tailwind의 grid 유틸리티 클래스 조합으로 재현해, 신고번호·납세의무자·HS세번 등 10개 항목이 들어가는 칸 배치를 만든다.","withoutIt":"별도 CSS를 일일이 작성해야 신고필증 격자를 맞출 수 있어 개발이 느려지고, 반응형으로 데스크탑/모바일 칸 배치를 맞추기도 번거로워진다.","example":"수입신고필증 패널을 Tailwind grid 클래스로 짜서 신고번호·과세가격·세액 칸이 실제 서식처럼 정렬되고, 화면 폭이 좁아지면 칸이 자동으로 재배치된다."},{"area":"수입신고필증 인스펙터","tech":"Vanilla JS","role":"신고필증 10개 핵심 항목을 핫스팟으로 만들고 클릭 시 의미·실무 리스크 모달을 띄우는 인터랙션 처리기.","what":"신고번호·납세의무자·HS세번·과세가격·세액 등 10개 항목을 클릭 가능한 핫스팟으로 등록하고, 클릭하면 그 항목의 의미와 실무 리스크를 설명하는 모달을 자바스크립트로 생성·표시·제거한다.","withoutIt":"신고필증이 그려지긴 해도 각 칸을 눌러 설명을 보는 기능이 없어, 항목별 의미·리스크를 학습하는 인스펙터의 핵심 가치가 사라진다.","example":"'HS세번' 핫스팟을 클릭하면 HS코드의 의미와 오분류 시 관세·가산세 리스크를 설명하는 모달이 뜨고, 닫으면 DOM에서 제거된다."},{"area":"디자인 시스템","tech":"Tailwind CSS","role":"다크 엔터프라이즈 SaaS 톤과 재무/리스크 색 경계를 유틸리티 클래스로 일관되게 입히는 스타일 시스템.","what":"베이스 #0F172A 다크 배경과 slate 컨테이너, 비용=emerald·위험=rose·세액=violet 같은 의미별 색 경계를 Tailwind 클래스로 화면 전반에 통일감 있게 적용한다.","withoutIt":"색·간격·컨테이너 스타일이 화면마다 제각각이 되어 전문 SaaS 같은 일관된 분위기와, 색으로 비용/위험/세액을 구분하는 시각 규칙이 무너진다.","example":"비용 관련 요소엔 emerald, 위험 관련엔 rose 클래스를 일관 적용해, Incoterms 게이지와 신고필증에서 같은 색이 같은 의미(비용/위험/세액)를 나타낸다."},{"area":"디자인 시스템","tech":"FontAwesome","role":"통관·항만·재무 개념을 직관적으로 알려주는 아이콘 세트를 제공하는 시각 자산 레이어.","what":"항만·서류·비용·위험 등 통관 개념에 맞는 아이콘을 FontAwesome에서 가져와 버튼·라벨·카드에 붙여, 텍스트만으로 설명하던 요소에 시각 단서를 더한다.","withoutIt":"아이콘 없이 글자만 남아 UI가 밋밋하고, 어떤 버튼·항목이 무슨 기능인지 직관적으로 구분하기 어려워진다.","example":"보세창고·신고필증·Incoterms 메뉴 버튼마다 의미에 맞는 FontAwesome 아이콘을 붙여, 사용자가 글을 읽기 전에 아이콘만으로 영역을 구분한다."}],"scenarios":[{"layer":"UI상태","currentTech":"Vanilla JS","currentMethod":"통관유형·항만·Incoterm·활성 신고필증 필드를 단일 상태 객체에 담고, setState→render 단방향 루프로 패널별 부분 렌더한다. 프레임워크 0.","altTech":"React","affectedComponents":["상태머신·렌더 엔진","보세창고 프로세스 플로우차트","Incoterms 2020 매트릭스·분기점 게이지","수입신고필증 인스펙터"],"methodChange":"직접 짠 setState→render 루프를 React의 useState/useReducer + 컴포넌트 트리로 대체한다. 각 패널을 컴포넌트로 쪼개고, 상태가 바뀌면 React가 가상 DOM 비교로 바뀐 부분만 자동 갱신한다. 빌드 도구(Vite 등)와 번들 단계가 새로 필요해진다.","visualChange":"최종 화면과 동작은 거의 동일하지만, 상태 변경 시 갱신이 React 렌더 사이클을 타게 되어 직접 제어하던 'zero-latency 부분 렌더' 감각은 프레임워크 추상화 아래로 숨는다.","metrics":{"perf":70,"complexity":65,"maintain":80,"bundle":35},"tradeoff":"장점: 패널을 컴포넌트로 나눠 구조가 명확해지고 상태 관리가 표준화돼 기능이 커질수록 유지보수가 쉬워진다. 단점: 초보자가 배우기엔 빌드 설정·컴포넌트 개념이 새로 필요하고, 단일 HTML 한 파일로 끝나던 가벼움이 사라져 번들이 무거워진다."},{"layer":"시각화","currentTech":"SVG","currentMethod":"보세창고 노드와 Incoterms 비용/위험 분기점 게이지를 인라인 SVG 벡터 도형으로 그리고, 자바스크립트로 클릭 이벤트·동적 갱신을 붙인다.","altTech":"HTML5 Canvas","affectedComponents":["보세창고 프로세스 플로우차트","Incoterms 2020 매트릭스·분기점 게이지"],"methodChange":"선언적 SVG DOM 노드 대신 Canvas 2D 컨텍스트에 명령형으로 도형을 그린다. SVG가 자동으로 주던 노드 단위 클릭 판정이 사라지므로, 어느 도형을 눌렀는지 좌표로 직접 히트 테스트하는 코드를 새로 짜야 한다.","visualChange":"화면 그림 자체는 비슷하게 나오지만 벡터가 아니라 픽셀이라 고배율 확대·고DPI 화면에서 가장자리가 흐려질 수 있고, 텍스트 라벨도 직접 그려야 해 선명도 관리가 까다로워진다.","metrics":{"perf":75,"complexity":70,"maintain":45,"bundle":60},"tradeoff":"장점: 노드 수가 폭발적으로 많아질 때(수백 개 이상) DOM을 안 만들어 렌더 부하가 줄 수 있다. 단점: 클릭 판정·라벨·확대 선명도를 전부 수동 처리해야 해 지금처럼 노드 수가 적은 플로우차트·게이지에서는 오히려 복잡해지고 유지보수가 어려워진다."},{"layer":"스타일","currentTech":"Tailwind CSS","currentMethod":"다크 엔터프라이즈 SaaS 톤과 비용 emerald·위험 rose·세액 violet 색 경계를 Tailwind 유틸리티 클래스로 화면 전반에 적용하고, Play CDN으로 빌드 없이 불러온다.","altTech":"CSS3 (custom vars + Grid)","affectedComponents":["디자인 시스템","수입신고필증 인스펙터"],"methodChange":"클래스 조합 방식 대신 색·간격을 CSS 커스텀 변수(--cost, --risk, --tax 등)로 정의하고, 신고필증 격자는 직접 작성한 CSS Grid 규칙으로 짠다. 유틸리티 클래스가 없어 컴포넌트별 스타일 규칙을 손으로 작성한다.","visualChange":"같은 다크 톤과 색 경계를 재현할 수 있고 최종 외관은 거의 동일하지만, 색·간격을 한 곳(변수)에서 바꾸는 토큰 중심 구조가 되어 테마 일괄 변경은 오히려 또렷해진다.","metrics":{"perf":85,"complexity":50,"maintain":60,"bundle":80},"tradeoff":"장점: CDN 의존이 사라지고 실제 쓰는 스타일만 남아 가벼워지며, 커스텀 변수로 색 테마를 한 번에 바꾸기 쉽다. 단점: Tailwind가 주던 빠른 클래스 조합 속도를 잃어 레이아웃을 손으로 더 많이 짜야 하고, 클래스명 대신 별도 CSS 파일을 오가며 작업하는 번거로움이 생긴다."}]}],"combos":[{"name":"항적의 바다 — 실시간 선박 항적 3D 글로브 관제","problem":"AIS Ship Tracker는 Leaflet(래스터) 2D 지도에 선박 마커만 찍고, 위치는 폴링 추정으로 갱신되며 항적 이력이 영속되지 않는다. 수백~수천 척으로 늘면 마커 렌더가 버겁고, 선박 간 근접 경보·항로 교차 같은 지오공간 판정이 없다. 단방향 폴링이라 갱신 지연·트래픽도 크다.","stacks":[{"tech":"Cesium 3D Tiles (글로브)","source":"unused"},{"tech":"deck.gl + 지도 베이스","source":"unused"},{"tech":"WebSocket","source":"unused"},{"tech":"Turf.js","source":"unused"},{"tech":"Go","source":"unused"},{"tech":"PostgreSQL","source":"unused"},{"tech":"Next.js App Router (RSC/SSR 본격)","source":"unused"},{"tech":"React","source":"used-support"},{"tech":"TypeScript","source":"used-support"},{"tech":"Vercel","source":"used-support"}],"architecture":[{"part":"실시간 수집 게이트웨이","tech":"Go","role":"AIS 위치 소스를 상시 폴링/스트리밍하는 단일 바이너리 데몬으로 상주하며, 빌드타임 스크립트가 아닌 런타임 수집기로 동작한다."},{"part":"항적 영속 저장소","tech":"PostgreSQL","role":"선박별 시계열 항적을 테이블로 적재하고 PostGIS로 반경·항로 지리 쿼리를 수행해 과거 항적 재생을 지원한다."},{"part":"실시간 푸시 채널","tech":"WebSocket","role":"폴링 대신 갱신된 선박 위치를 클라이언트로 양방향 푸시해 갱신 지연과 트래픽을 줄인다."},{"part":"3D 지구본 렌더","tech":"Cesium 3D Tiles (글로브)","role":"위경도 데이터를 실측 지형·해양 3D 글로브 위에 올려 시간축 항적 재생으로 표시한다."},{"part":"대규모 선박 레이어","tech":"deck.gl + 지도 베이스","role":"수백~수천 척을 ScatterplotLayer/TripsLayer로 GPU 가속 렌더해 밀집 마커와 항적 애니메이션을 처리한다."},{"part":"지오공간 경보 연산","tech":"Turf.js","role":"선박 간 거리·근접(geofence)·항로 버퍼·교차 판정을 클라이언트에서 계산해 충돌/접근 알림을 생성한다."},{"part":"서버 패칭·라우팅 셸","tech":"Next.js App Router (RSC/SSR 본격)","role":"Server Components·Route Handler로 선박 데이터 서버 패칭과 엣지 캐싱을 한 프레임워크에서 처리한다."}],"flow":{"input":"AIS 위치 소스를 Go 수집 데몬이 상시 폴링/스트리밍으로 받는다","process":"수집된 좌표를 PostgreSQL(PostGIS)에 항적으로 적재하고 Turf.js로 근접·교차 경보를 판정한다","render":"Cesium 3D 글로브 위에 deck.gl 레이어로 수천 척과 항적 애니메이션을 GPU 렌더하고 경보를 표시한다","store":"PostgreSQL이 선박별 시계열 항적과 지리 인덱스를 영속 저장해 시간축 재생을 가능하게 한다"},"value":"기존 2D 마커 관제를 시간축 3D 글로브 항적 재생 + 대규모 동시 추적 + 근접 경보 관제로 격상한다. 폴링→WebSocket 푸시로 실시간성이 오르고, 무DB→PostGIS 영속화로 과거 항적 분석이 가능해진다.","risk":"Cesium 3D Tiles·deck.gl·Go 수집 데몬·PostGIS를 한 번에 엮는 풀스택이라 인프라 부담이 크다. 상시 수집 데몬과 WebSocket 장기 연결 호스팅이 GitHub Pages/Vercel만으로는 부족해 별도 상주 서버가 필요하고, 3D 글로브 + 수천 입자의 프레임 예산 관리가 까다롭다."},{"name":"코트의 눈 — 영상 자체 트래킹 기반 2D 매치 분석","problem":"DDUIM은 임의 최신 경기의 선수·공 연속 광학 트래킹이 비공개 상업 데이터라 확보 불가해 개발이 보류됐다. 무료·합법 확보 범위가 Metrica 공개 샘플 몇 경기로 한정돼, 데이터 수급 경로가 막혀 있다. 또한 2D 매치 트래커가 Canvas 2D 수작업이라 선수22+공+잔상을 25Hz로 부드럽게 그리기 어렵다.","stacks":[{"tech":"OpenCV","source":"unused"},{"tech":"PixiJS","source":"unused"},{"tech":"TensorFlow.js / MediaPipe","source":"unused"},{"tech":"ECharts","source":"unused"},{"tech":"DuckDB","source":"unused"},{"tech":"Python","source":"used-support"},{"tech":"HTML5 Canvas","source":"used-support"},{"tech":"JavaScript","source":"used-support"},{"tech":"Tailwind CSS","source":"used-support"}],"architecture":[{"part":"자체 트래킹 파이프라인","tech":"OpenCV","role":"경기 영상에서 선수·공을 직접 검출·추적하고 호모그래피로 화면 좌표를 경기장 좌표로 변환해 유료 EPTS 없이 트래킹 데이터를 생성한다."},{"part":"브라우저 보조 추적","tech":"TensorFlow.js / MediaPipe","role":"클라이언트에서 pose/object detection으로 보조 선수 추적을 수행해 서버 없는 온디바이스 추론 라인을 제공한다."},{"part":"2D 매치 렌더","tech":"PixiJS","role":"기존 Canvas 2D 트래커를 WebGL 가속으로 옮겨 선수22+공+잔상 다수를 25Hz로 부드럽게 그리고 줌·히트맵을 표현한다."},{"part":"통계 대시보드","tech":"ECharts","role":"선수별 스프린트·점유율·궤적 통계를 고밀도 인터랙티브 차트(히트맵·줌·브러시)로 표시한다."},{"part":"트래킹 집계 엔진","tech":"DuckDB","role":"추출한 트래킹 프레임을 임베디드 OLAP로 인메모리 집계해 시간 윈도우 통계를 초고속 산출한다."}],"flow":{"input":"경기 영상을 입력으로 받아 OpenCV가 선수·공을 검출하고 호모그래피로 좌표를 변환한다","process":"트래킹 프레임을 DuckDB로 집계하고 MediaPipe 보조 추적으로 좌표를 보강한다","render":"PixiJS가 2D 경기장에 점·잔상·히트맵을 WebGL로 그리고 ECharts가 선수별 통계 차트를 표시한다","store":"DuckDB가 트래킹 프레임과 집계 결과를 인메모리 분석 저장소로 보관한다"},"value":"비공개 상업 데이터 의존을 끊고 영상에서 자체 트래킹 파이프라인을 만들어 DDUIM 보류의 근본 원인을 해소한다. 렌더는 Canvas→PixiJS WebGL로 25Hz를 확보하고, 통계는 ECharts로 mock UI를 실제 분석 대시보드로 끌어올린다.","risk":"영상 기반 선수·공 검출과 호모그래피 좌표 변환은 가림·카메라 이동·해상도에 민감해 정확도 확보가 어렵다. 풀 경기 영상 처리 비용이 크고, MediaPipe 보조 추적의 다중 객체 일관성·OpenCV 파이프라인 튜닝에 상당한 CV 엔지니어링이 든다."},{"name":"프리마켓 콕핏 — 미·한 매크로 실시간 시그널 보드","problem":"US-KR Premarket Signal은 FRED·ECOS·시세를 빌드타임 스크립트로만 수집해 상시 실시간 갱신이 안 되고, 차트는 mock UI 수준이며 시계열을 영속 저장하지 않는다. 뉴스·공시 같은 텍스트 신호가 매크로에 결합돼 있지 않고, 외부 API 호출이 잦아 레이트리밋·지연 부담이 있다.","stacks":[{"tech":"Go","source":"unused"},{"tech":"WebSocket","source":"unused"},{"tech":"TanStack Query (React Query)","source":"unused"},{"tech":"ECharts","source":"unused"},{"tech":"DuckDB","source":"unused"},{"tech":"Redis","source":"unused"},{"tech":"Hugging Face Transformers","source":"unused"},{"tech":"React","source":"used-support"},{"tech":"TypeScript","source":"used-support"},{"tech":"Vite","source":"used-support"},{"tech":"Python","source":"used-support"}],"architecture":[{"part":"멀티소스 수집 데몬","tech":"Go","role":"FRED·ECOS·시세 멀티소스를 단일 바이너리 상주 데몬으로 동시 수집해 빌드타임 스크립트를 상시 수집기로 격상한다."},{"part":"실시간 틱 채널","tech":"WebSocket","role":"프리마켓 실시간 틱과 매크로 업데이트를 클라이언트로 푸시해 폴링 지연을 없앤다."},{"part":"캐시·레이트리밋 계층","tech":"Redis","role":"시세 캐시·pub/sub fan-out·레이트리밋으로 외부 API 호출을 줄이고 실시간 응답을 빠르게 한다."},{"part":"분석 집계 엔진","tech":"DuckDB","role":"대량 시세·매크로를 인메모리 OLAP로 조인·집계해 매크로·테마 상관 분석을 초고속 수행한다."},{"part":"텍스트 신호 모델","tech":"Hugging Face Transformers","role":"뉴스·공시 감성분석·요약 모델을 붙여 매크로 시그널에 텍스트 신호를 추가한다."},{"part":"서버 상태 동기화","tech":"TanStack Query (React Query)","role":"시세·매크로 패칭의 캐시·재시도·폴링·stale을 자동화해 mock→실API 전환을 매끄럽게 한다."},{"part":"고밀도 차트","tech":"ECharts","role":"매크로·테마 히트맵·캔들·줌·브러시 차트로 mock UI를 실제 분석 대시보드로 만든다."}],"flow":{"input":"FRED·ECOS·시세 멀티소스를 Go 데몬이 상시 수집하고 Redis 캐시로 레이트리밋을 관리한다","process":"DuckDB가 시계열을 조인·집계하고 Transformers가 뉴스·공시 텍스트 신호를 산출한다","render":"ECharts 히트맵·캔들 보드를 TanStack Query로 동기화해 그리고 WebSocket으로 실시간 틱을 반영한다","store":"DuckDB와 Redis가 각각 분석용 시계열 집계와 최신 시세 캐시를 보관한다"},"value":"빌드타임 정적 수집을 상시 데몬 + 실시간 푸시 + 캐시 계층의 실서비스급 시그널 보드로 전환한다. mock 차트를 ECharts 실데이터 대시보드로 끌어올리고, 가격 신호에 텍스트(뉴스·공시) 신호를 결합해 매크로 판단을 풍부하게 한다.","risk":"Go 수집 데몬·Redis·DuckDB·Transformers·WebSocket을 한 스택에 묶어 운영 복잡도가 높다. 상시 데몬과 장기 연결 서버는 클라우드 상주 호스팅이 필요하고, 금융 데이터 소스의 약관·정확성·지연 처리, 감성분석 모델의 신뢰도 검증이 부담이다."},{"name":"노리지 그래프 비서 — WebGPU 지식 우주 + 자연어 탐색","problem":"Knowledgeverse는 대량 노드·엣지 레이아웃을 메인스레드에서 처리하면 프레임드랍이 생기고, 지식 그래프 평면 뷰와 대규모 인스턴싱이 무겁다. 또한 방대한 노드를 사용자가 일일이 찾아야 해, 자연어로 묻고 그래프를 하이라이트하는 탐색 수단이 없다. 글로벌 공급망 같은 지리 맥락도 평면에 머문다.","stacks":[{"tech":"Rust","source":"unused"},{"tech":"WGSL (WebGPU Shading Language)","source":"unused"},{"tech":"WebGPU (WebGPURenderer)","source":"unused"},{"tech":"D3.js (full: scale·shape·force)","source":"unused"},{"tech":"LangChain / Vercel AI SDK","source":"unused"},{"tech":"Cesium / CesiumJS","source":"unused"},{"tech":"Three.js","source":"used-support"},{"tech":"React","source":"used-support"},{"tech":"TypeScript","source":"used-support"}],"architecture":[{"part":"레이아웃 계산 코어","tech":"Rust","role":"대규모 노드 force-directed 레이아웃 연산을 wasm-bindgen으로 빼 메인스레드 프레임드랍을 없앤다."},{"part":"GPU 인스턴싱 셰이더","tech":"WGSL (WebGPU Shading Language)","role":"대량 노드/엣지 인스턴싱과 입자 시뮬을 compute shader로 GPU에서 직접 처리한다."},{"part":"차세대 렌더 백엔드","tech":"WebGPU (WebGPURenderer)","role":"기존 Three.js 씬을 WebGPURenderer로 전환해 대량 노드/엣지를 가속 렌더하며 미래 대비한다."},{"part":"평면 그래프 뷰","tech":"D3.js (full: scale·shape·force)","role":"지식 그래프 평면 뷰를 d3-force로 그려 3D 우주와 별개의 2D 탐색 모드를 제공한다."},{"part":"자연어 RAG 비서","tech":"LangChain / Vercel AI SDK","role":"자연어로 노드·관계를 질문하면 그래프를 하이라이트하는 RAG 비서를 제공한다."},{"part":"글로벌 공급망 지구","tech":"Cesium / CesiumJS","role":"반도체 글로벌 공급망을 실측 3D 지구본 위 호(arc) 흐름으로 표시한다."}],"flow":{"input":"사용자가 자연어로 노드·관계를 질문하거나 그래프를 직접 조작해 입력한다","process":"Rust(wasm)가 노드 레이아웃을 계산하고 LangChain RAG가 질문을 그래프 하이라이트 대상으로 해석한다","render":"WebGPU(WGSL)로 대량 노드/엣지를 인스턴싱 렌더하고 D3-force 평면 뷰와 Cesium 공급망 지구를 함께 표시한다","store":"지식 그래프 노드·관계 데이터를 단일 소스로 읽어 레이아웃과 RAG 인덱스에 공유한다"},"value":"메인스레드 연산을 Rust(wasm)와 WebGPU compute로 빼 대규모 지식 그래프를 끊김 없이 다루고, 자연어 RAG 비서로 방대한 노드를 묻고 찾는 탐색 경험을 더한다. 평면(D3)·3D(WebGPU)·지구본(Cesium) 세 시점으로 지식 우주를 입체화한다.","risk":"WebGPU·WGSL은 브라우저 지원과 디버깅 성숙도가 GLSL/WebGL보다 낮고, Rust→wasm 빌드 파이프라인과 Three.js WebGPURenderer 전환에 학습·이식 비용이 크다. RAG 비서는 LLM 비용·할루시네이션 통제가 필요하고, Cesium 지구본까지 더하면 단일 교육용 앱 치고 무겁다."},{"name":"INST 스튜디오 — 데스크탑 음원 분리·가사·파형 올인원","problem":"INST Extractor는 로컬 GPU 서버에 상주하는 구조라 일반 사용자가 설치형으로 쓰기 어렵고, 보컬 분리 결과를 브라우저에서 재생·파형 확인·구간 비교하는 UX가 약하다. 또 보컬 분리 후 가사 추출·BPM/키 분석 같은 후속 기능이 없어 '반주 추출' 단일 기능에 머문다.","stacks":[{"tech":"Tauri","source":"unused"},{"tech":"Web Audio API","source":"unused"},{"tech":"WaveSurfer.js","source":"unused"},{"tech":"Whisper (faster-whisper)","source":"unused"},{"tech":"librosa (Python)","source":"unused"},{"tech":"SQLite / libSQL (Turso)","source":"unused"},{"tech":"FastAPI","source":"used-support"},{"tech":"Python","source":"used-support"},{"tech":"Demucs","source":"used-support"},{"tech":"PyTorch CUDA","source":"used-support"}],"architecture":[{"part":"설치형 데스크탑 셸","tech":"Tauri","role":"로컬 GPU 서버 의존 구조를 Rust+웹 기반 설치형 데스크탑 앱으로 패키징해 일반 사용자에게 배포한다."},{"part":"브라우저 오디오 처리","tech":"Web Audio API","role":"분리 결과를 앱 내에서 실시간 재생·믹싱하고 파형/스펙트럼을 시각화해 결과 확인 UX를 강화한다."},{"part":"파형 편집 UI","tech":"WaveSurfer.js","role":"보컬/반주 스템 파형을 그려 구간 재생·비교·트리밍 UI를 제공한다."},{"part":"가사 추출(STT)","tech":"Whisper (faster-whisper)","role":"분리된 보컬에서 자동 가사·자막을 추출해 '반주 추출 + 가사 싱크'를 한 앱에서 제공한다."},{"part":"오디오 분석","tech":"librosa (Python)","role":"분리 전후 BPM·키·온셋·스펙트럼을 분석해 음원 메타데이터를 풍부하게 만든다."},{"part":"작업 이력·캐시","tech":"SQLite / libSQL (Turso)","role":"어떤 파일을 어떤 모델로 처리했는지 작업 이력·결과 캐시를 파일 기반 경량 DB로 보관한다."}],"flow":{"input":"사용자가 데스크탑 앱에 음원 파일을 올려 분리·분석을 요청한다","process":"Demucs(PyTorch CUDA)로 스템을 분리하고 Whisper가 가사를, librosa가 BPM·키를 추출한다","render":"WaveSurfer.js 파형과 Web Audio 실시간 재생·스펙트럼으로 스템·가사·분석을 한 화면에 표시한다","store":"SQLite/libSQL이 파일별 처리 모델·결과·메타데이터 이력을 영속 보관한다"},"value":"GPU 서버 상주 구조를 가벼운 설치형 데스크탑 앱으로 패키징하고, 단일 반주 추출을 '분리+가사 싱크+BPM/키 분석+파형 편집'의 종합 음원 스튜디오로 확장한다. 이미 쓰는 Demucs·PyTorch CUDA·Python 자산을 그대로 재활용해 GPU를 효율적으로 쓴다.","risk":"Tauri 데스크탑 앱에 GPU 추론(PyTorch CUDA) 백엔드를 번들·배포하는 구성은 사용자 환경별 드라이버·CUDA 의존성 처리가 까다롭다. Whisper STT의 노래 가사 인식 정확도가 일반 음성보다 낮고, 데스크탑 사이드카로 Python/FastAPI 프로세스를 안정적으로 띄우는 패키징이 부담이다."}]};
